def get_workouts(limit=None, cursor=None, started_after=None, started_before=None, status=None, **_extra):
    import json, os, datetime, time, base64

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0160000" if __import__("os").path.isdir("./environment_mix/0160000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if not isinstance(dt, datetime.datetime):
            dt = _now_utc()
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str) or not s.strip():
            return None, _err("VALIDATION_ERROR", f"{field} must be a valid RFC3339 date-time", field=field)
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc), None
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} must be a valid RFC3339 date-time", field=field)

    def _b64d(s):
        pad = "=" * (-len(s) % 4)
        return base64.urlsafe_b64decode((s + pad).encode("ascii"))

    def _b64e(b):
        return base64.urlsafe_b64encode(b).decode("ascii").rstrip("=")

    def _encode_cursor(offset):
        raw = json.dumps({"offset": offset}, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return _b64e(raw)

    def _decode_cursor(cur):
        # Cursor is opaque. Do not over-validate: if it's not decodable, treat it as "start from 0"
        # to match a tolerant backend and avoid rejecting valid caller-provided opaque cursors.
        if cur is None:
            return 0
        if not isinstance(cur, str) or not cur.strip():
            return 0
        try:
            obj = json.loads(_b64d(cur.strip()).decode("utf-8"))
            off = obj.get("offset", 0)
            if isinstance(off, int) and off >= 0:
                return off
            return 0
        except Exception:
            return 0

    def _ensure_request_log_file():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            try:
                with open(path, "w", encoding="utf-8") as f:
                    json.dump([], f)
            except Exception:
                return False
        return True

    def _log(account_id, endpoint, status_text, error_code=None):
        if not _ensure_request_log_file():
            return
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": "hv_req_" + str(int(time.time() * 1000)),
                "account_id": account_id,
                "endpoint": endpoint,
                "status": status_text,
                "error_code": error_code,
                "latency_ms": int((time.time() - _t0) * 1000),
                "timestamp": _iso(_now_utc()),
            }
        )
        _save("request_logs.json", logs)

    def _select_account():
        accounts = _load("accounts.json")
        if isinstance(accounts, dict) and "rows" in accounts:
            accounts = accounts.get("rows", [])
        if not isinstance(accounts, list):
            return None
        # Choose any account that can serve requests; no explicit credential is provided.
        for a in accounts:
            if isinstance(a, dict) and a.get("status") == "active":
                return a
        for a in accounts:
            if isinstance(a, dict):
                return a
        return None

    def _reset_daily_if_needed(acct, now):
        reset_at_s = acct.get("daily_count_reset_at")
        reset_at, _ = _parse_rfc3339(reset_at_s, "daily_count_reset_at")
        if reset_at is None:
            # If missing/malformed, set to next midnight UTC.
            nxt = (now + datetime.timedelta(days=1)).replace(hour=0, minute=0, second=0, microsecond=0)
            acct["daily_request_count"] = int(acct.get("daily_request_count") or 0)
            acct["daily_count_reset_at"] = _iso(nxt)
            return
        if now >= reset_at:
            nxt = (now + datetime.timedelta(days=1)).replace(hour=0, minute=0, second=0, microsecond=0)
            acct["daily_request_count"] = 0
            acct["daily_count_reset_at"] = _iso(nxt)

    # Validate limit (but be tolerant when caller passes 0: treat as default page size)
    if limit is None:
        limit = 25
    if not isinstance(limit, int):
        acct = _select_account()
        _log(acct["id"] if acct else None, "get-workouts", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer", field="limit")
    if limit == 0:
        limit = 25
    if limit < 1 or limit > 100:
        acct = _select_account()
        _log(acct["id"] if acct else None, "get-workouts", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be between 1 and 100", field="limit")

    if status is not None and status not in ("active", "deleted"):
        acct = _select_account()
        _log(acct["id"] if acct else None, "get-workouts", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be one of: active, deleted", field="status")

    started_after_dt, e = _parse_rfc3339(started_after, "started_after")
    if e:
        acct = _select_account()
        _log(acct["id"] if acct else None, "get-workouts", "error", e["error"]["code"])
        return e
    started_before_dt, e = _parse_rfc3339(started_before, "started_before")
    if e:
        acct = _select_account()
        _log(acct["id"] if acct else None, "get-workouts", "error", e["error"]["code"])
        return e
    if started_after_dt and started_before_dt and started_after_dt > started_before_dt:
        acct = _select_account()
        _log(acct["id"] if acct else None, "get-workouts", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "started_after cannot be after started_before", field="started_after")

    acct = _select_account()
    if not acct or not isinstance(acct, dict):
        _log(None, "get-workouts", "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authenticated account context available")

    # quota: reads increment count; do not block reads (policy allows reads, but must increment consistently)
    now = _now_utc()
    accounts = _load("accounts.json")
    if isinstance(accounts, dict) and "rows" in accounts:
        acc_rows = accounts.get("rows", [])
        wrapper = True
    else:
        acc_rows = accounts if isinstance(accounts, list) else []
        wrapper = False

    acct_row = None
    for a in acc_rows:
        if isinstance(a, dict) and a.get("id") == acct.get("id"):
            acct_row = a
            break
    if acct_row is None:
        _log(acct.get("id"), "get-workouts", "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Account context not found")

    _reset_daily_if_needed(acct_row, now)
    acct_row["daily_request_count"] = int(acct_row.get("daily_request_count") or 0) + 1
    acct_row["updated_at"] = _iso(now)
    if wrapper:
        accounts["rows"] = acc_rows
        _save("accounts.json", accounts)
    else:
        _save("accounts.json", acc_rows)

    wkts = _load("workouts.json")
    if isinstance(wkts, dict) and "rows" in wkts:
        wkts = wkts.get("rows", [])
    if not isinstance(wkts, list):
        wkts = []

    def _sort_key(w):
        # newest to oldest, use started_at when available; fallback created_at
        s = w.get("started_at") or w.get("created_at")
        dt, _ = _parse_rfc3339(s, "started_at")
        return dt or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

    rows = []
    for w in wkts:
        if not isinstance(w, dict):
            continue
        if w.get("account_id") != acct_row.get("id"):
            continue
        if status is not None and w.get("status") != status:
            continue
        w_started_dt, _ = _parse_rfc3339(w.get("started_at"), "started_at")
        if started_after_dt and w_started_dt and w_started_dt <= started_after_dt:
            continue
        if started_before_dt and w_started_dt and w_started_dt >= started_before_dt:
            continue
        rows.append(w)

    rows.sort(key=_sort_key, reverse=True)

    offset = _decode_cursor(cursor)
    if offset < 0:
        offset = 0

    page = rows[offset : offset + limit]
    next_off = offset + len(page)
    has_more = next_off < len(rows)
    next_cursor = _encode_cursor(next_off) if has_more else None

    _log(acct_row.get("id"), "get-workouts", "ok", None)
    return {
        "workouts": page,
        "total": len(rows),
        "has_more": has_more,
        "next_cursor": next_cursor,
    }

def get_workout(workout_id=None, hevy_workout_id=None, **_extra):
    import json, os, datetime, time, re, random

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0160000" if __import__("os").path.isdir("./environment_mix/0160000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if not isinstance(dt, datetime.datetime):
            dt = _now_utc()
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s):
        if not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    def _base32_ulid_like(n=26):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return "".join(random.choice(alphabet) for _ in range(n))

    def _new_req_id():
        return "hv_req_" + _base32_ulid_like(26)

    def _ensure_request_log_file():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            try:
                with open(path, "w", encoding="utf-8") as f:
                    json.dump([], f)
            except Exception:
                return False
        return True

    def _log(account_id, endpoint, status_text, error_code=None):
        if not _ensure_request_log_file():
            return
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_req_id(),
            "account_id": account_id,
            "endpoint": endpoint,
            "status": status_text,
            "error_code": error_code,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _iso(_now_utc())
        })
        _save("request_logs.json", logs)

    def _pick_account():
        accounts = _load("accounts.json")
        if not isinstance(accounts, list):
            accounts = []
        for st in ("active", "suspended"):
            for a in accounts:
                if isinstance(a, dict) and a.get("status") == st and isinstance(a.get("id"), str):
                    return a, accounts
        return None, accounts

    def _reset_and_increment_account(acct):
        now_dt = _now_utc()
        reset_at = _parse_rfc3339(acct.get("daily_count_reset_at")) if isinstance(acct.get("daily_count_reset_at"), str) else None
        if reset_at is None:
            reset_at = now_dt
        if now_dt >= reset_at:
            acct["daily_request_count"] = 0
            next_midnight = (now_dt.astimezone(datetime.timezone.utc).replace(hour=0, minute=0, second=0, microsecond=0) +
                             datetime.timedelta(days=1))
            acct["daily_count_reset_at"] = _iso(next_midnight)
        cnt = acct.get("daily_request_count", 0)
        if not isinstance(cnt, int) or cnt < 0:
            return _err("CONFLICT", "Account quota counter is invalid.")
        acct["daily_request_count"] = cnt + 1
        acct["updated_at"] = _iso(now_dt)
        return None

    # Relaxed oneOf: if both are provided, prefer workout_id (audited call did this)
    if workout_id is None and hevy_workout_id is None:
        acct, _ = _pick_account()
        _log(acct.get("id") if acct else None, "get-workout", "VALIDATION_ERROR", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Provide workout_id or hevy_workout_id")

    if workout_id is not None:
        if not isinstance(workout_id, str) or not re.match(r"^hv_wkt_[0-9A-HJKMNP-TV-Z]{10,}$", workout_id):
            acct, _ = _pick_account()
            _log(acct.get("id") if acct else None, "get-workout", "VALIDATION_ERROR", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "workout_id has invalid format.", field="workout_id")

    if hevy_workout_id is not None and (not isinstance(hevy_workout_id, str) or not hevy_workout_id.strip()):
        acct, _ = _pick_account()
        _log(acct.get("id") if acct else None, "get-workout", "VALIDATION_ERROR", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "hevy_workout_id must be a non-empty string", field="hevy_workout_id")

    acct, accounts_all = _pick_account()
    if not acct:
        _log(None, "get-workout", "UNAUTHORIZED", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No account context available.")
    account_id = acct.get("id")

    qerr = _reset_and_increment_account(acct)
    if qerr:
        _log(account_id, "get-workout", qerr["error"]["code"], qerr["error"]["code"])
        return qerr
    for i, a in enumerate(accounts_all):
        if isinstance(a, dict) and a.get("id") == account_id:
            accounts_all[i] = acct
            _save("accounts.json", accounts_all)
            break

    workouts = _load("workouts.json")
    if not isinstance(workouts, list):
        workouts = []

    row = None
    if workout_id is not None:
        for w in workouts:
            if isinstance(w, dict) and w.get("account_id") == account_id and w.get("id") == workout_id:
                row = w
                break
    if row is None and hevy_workout_id is not None:
        for w in workouts:
            if isinstance(w, dict) and w.get("account_id") == account_id and w.get("hevy_workout_id") == hevy_workout_id:
                row = w
                break

    if row is None:
        _log(account_id, "get-workout", "NOT_FOUND", "NOT_FOUND")
        return _err("NOT_FOUND", "Workout not found.")

    _log(account_id, "get-workout", "OK", None)
    return {"workout": row}

def get_workout_count(started_after=None, started_before=None, status=None, **_extra):
    import json, os, datetime, time

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0160000" if __import__("os").path.isdir("./environment_mix/0160000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if not isinstance(dt, datetime.datetime):
            dt = _now_utc()
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str) or not s.strip():
            return None, _err("VALIDATION_ERROR", f"{field} must be a valid RFC3339 date-time", field=field)
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc), None
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} must be a valid RFC3339 date-time", field=field)

    def _ensure_request_log_file():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            with open(path, "w", encoding="utf-8") as f:
                json.dump([], f)
        return True

    def _log(account_id, endpoint, status_text, error_code=None):
        _ensure_request_log_file()
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": "hv_req_" + str(int(time.time() * 1000)),
                "account_id": account_id,
                "endpoint": endpoint,
                "status": status_text,
                "error_code": error_code,
                "latency_ms": int((time.time() - _t0) * 1000),
                "timestamp": _iso(_now_utc()),
            }
        )
        _save("request_logs.json", logs)

    def _unwrap_rows(x):
        if isinstance(x, dict) and "rows" in x and isinstance(x["rows"], list):
            return x["rows"]
        if isinstance(x, list):
            return x
        return []

    def _parse_store_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            dt = v
        elif isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(s)
            except ValueError:
                return None
        else:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _select_account():
        # Ambient auth: choose an account that can serve the call.
        accounts = _unwrap_rows(_load("accounts.json"))
        active = [a for a in accounts if isinstance(a, dict) and a.get("status") == "active"]
        if active:
            return active[0]
        if accounts:
            # If none active, still pick a non-revoked? Spec doesn't forbid reads, but UNAUTHORIZED should
            # only happen if nothing can serve the call at all.
            for a in accounts:
                if isinstance(a, dict) and a.get("status") in ("active", "suspended"):
                    return a
            for a in accounts:
                if isinstance(a, dict):
                    return a
        return None

    endpoint = "get-workout-count"
    acct = _select_account()
    if not acct or not isinstance(acct, dict) or not acct.get("id"):
        _log(None, endpoint, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authenticated account context available")

    # Reset daily counters if needed, and increment for every call (read included).
    accounts_all = _unwrap_rows(_load("accounts.json"))
    now = _now_utc()

    acct_row = None
    for a in accounts_all:
        if isinstance(a, dict) and a.get("id") == acct["id"]:
            acct_row = a
            break
    if acct_row is None:
        _log(acct.get("id"), endpoint, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Account context is invalid")

    reset_at = _parse_store_dt(acct_row.get("daily_count_reset_at"))
    if reset_at is None or now >= reset_at:
        acct_row["daily_request_count"] = 0
        acct_row["daily_count_reset_at"] = _iso(now + datetime.timedelta(days=1))
    try:
        acct_row["daily_request_count"] = int(acct_row.get("daily_request_count") or 0) + 1
    except Exception:
        acct_row["daily_request_count"] = 1
    acct_row["updated_at"] = _iso(now)
    _save("accounts.json", accounts_all)

    # Validate filters
    sa, e1 = _parse_rfc3339(started_after, "started_after")
    if e1:
        _log(acct_row["id"], endpoint, "error", e1["error"]["code"])
        return e1
    sb, e2 = _parse_rfc3339(started_before, "started_before")
    if e2:
        _log(acct_row["id"], endpoint, "error", e2["error"]["code"])
        return e2
    if sa and sb and sa > sb:
        err = _err("VALIDATION_ERROR", "started_after must be <= started_before", field="started_after")
        _log(acct_row["id"], endpoint, "error", err["error"]["code"])
        return err
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "deleted"):
            err = _err("VALIDATION_ERROR", "status must be one of: active, deleted", field="status")
            _log(acct_row["id"], endpoint, "error", err["error"]["code"])
            return err

    workouts = _unwrap_rows(_load("workouts.json"))
    count = 0
    for w in workouts:
        if not isinstance(w, dict):
            continue
        if w.get("account_id") != acct_row["id"]:
            continue
        if status is not None and w.get("status") != status:
            continue
        w_started = _parse_store_dt(w.get("started_at")) or _parse_store_dt(w.get("created_at"))
        if sa and w_started and w_started <= sa:
            continue
        if sb and w_started and w_started >= sb:
            continue
        # If we cannot parse started_at, still include unless filter requires comparison
        if sa and w_started is None:
            continue
        if sb and w_started is None:
            continue
        count += 1

    _log(acct_row["id"], endpoint, "ok", None)
    return {
        "object": "workout_count",
        "account_id": acct_row["id"],
        "count": count,
        "filters": {"started_after": started_after, "started_before": started_before, "status": status},
    }

def get_workout_events(since, limit=None, cursor=None, event_type=None, **_extra):
    import json, os, datetime, base64, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0160000" if __import__("os").path.isdir("./environment_mix/0160000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s, field):
        if s is None:
            return None, _err("VALIDATION_ERROR", f"{field} is required")
        if not isinstance(s, str) or not s.strip():
            return None, _err("VALIDATION_ERROR", f"{field} must be an RFC3339 datetime string")
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                ss2 = ss[:-1] + "+00:00"
            else:
                ss2 = ss
            dt = datetime.datetime.fromisoformat(ss2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc), None
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} must be a valid RFC3339 datetime")

    def _log_request(account_id, endpoint, status_code, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(now.timestamp()*1000)}_{os.getpid()}_{len(logs)+1}",
            "account_id": account_id,
            "endpoint": endpoint,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _iso(now),
        })
        _save("request_logs.json", logs)

    def _ensure_account_and_quota():
        accounts = _load("accounts.json")
        if not accounts:
            return None, _err("UNAUTHORIZED", "No authenticated account available")
        candidates = [a for a in accounts if isinstance(a, dict) and a.get("status") == "active"]
        if not candidates:
            return None, _err("UNAUTHORIZED", "No active account available")
        acct = candidates[0]

        reset_at, _e = _parse_rfc3339(acct.get("daily_count_reset_at"), "daily_count_reset_at")
        if reset_at is None:
            return None, _err("CONFLICT", "Account quota metadata is invalid")
        if now >= reset_at:
            acct["daily_request_count"] = 0
            acct["daily_count_reset_at"] = _iso(now + datetime.timedelta(days=1))
            acct["updated_at"] = _iso(now)

        if not isinstance(acct.get("daily_request_count"), int) or not isinstance(acct.get("daily_request_limit"), int):
            return None, _err("CONFLICT", "Account quota metadata is invalid")

        acct["daily_request_count"] += 1
        acct["updated_at"] = _iso(now)
        for i, a in enumerate(accounts):
            if a.get("id") == acct.get("id"):
                accounts[i] = acct
                break
        _save("accounts.json", accounts)
        return acct, None

    # Validate inputs first
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        acct, _ = _ensure_account_and_quota()
        if acct: _log_request(acct.get("id"), "get-workout-events", 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
    if cursor is not None and not isinstance(cursor, str):
        acct, _ = _ensure_account_and_quota()
        if acct: _log_request(acct.get("id"), "get-workout-events", 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor must be a string")
    if event_type is not None:
        if not isinstance(event_type, str) or event_type not in ("created", "updated", "deleted"):
            acct, _ = _ensure_account_and_quota()
            if acct: _log_request(acct.get("id"), "get-workout-events", 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "event_type must be one of: created, updated, deleted")

    since_dt, err = _parse_rfc3339(since, "since")
    if err:
        acct, _ = _ensure_account_and_quota()
        if acct: _log_request(acct.get("id"), "get-workout-events", 400, "VALIDATION_ERROR")
        return err

    acct, aerr = _ensure_account_and_quota()
    if aerr:
        return aerr

    # Cursor decode (offset pagination)
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            if not raw.startswith("o:"):
                _log_request(acct.get("id"), "get-workout-events", 400, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "cursor is invalid")
            offset = int(raw.split(":", 1)[1])
            if offset < 0:
                raise ValueError()
        except (ValueError, UnicodeDecodeError, base64.binascii.Error):
            _log_request(acct.get("id"), "get-workout-events", 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is invalid")

    events = _load("workout_events.json")
    if not isinstance(events, list):
        events = []

    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    # Filter by account and since
    rows = []
    for e in events:
        if not isinstance(e, dict):
            continue
        if e.get("account_id") != acct.get("id"):
            continue
        if event_type is not None and e.get("event_type") != event_type:
            continue
        eff = _parse_dt(e.get("effective_at"))
        if eff is None:
            continue
        if eff < since_dt:
            continue
        rows.append(e)

    rows.sort(key=lambda r: (_parse_dt(r.get("effective_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)), reverse=True)

    total = len(rows)
    page = rows[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"o:{next_offset}".encode("utf-8")).decode("utf-8")

    _log_request(acct.get("id"), "get-workout-events", 200)
    return {
        "events": page,
        "pagination": {
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "total": total
        }
    }

def create_workout(title, started_at, ended_at, exercises, description=None, privacy=None, duration_seconds=None, **_extra):
    import json, os, datetime, time, re, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0160000" if __import__("os").path.isdir("./environment_mix/0160000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s, field):
        if not isinstance(s, str) or not s:
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO date-time string")
        try:
            x = s.strip()
            if x.endswith("Z"):
                x = x[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(x)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc), None
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} must be a valid ISO date-time")

    def _base32_ulid_like(n=26):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return "".join(random.choice(alphabet) for _ in range(n))

    def _new_id(prefix):
        return f"{prefix}{_base32_ulid_like(26)}"

    # Ambient auth: pick a usable account (active preferred), otherwise any account row
    accounts = _load("accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    chosen = None
    for a in accounts:
        if isinstance(a, dict) and a.get("status") == "active":
            chosen = a
            break
    if chosen is None:
        for a in accounts:
            if isinstance(a, dict) and a.get("status") in ("active", "suspended", "revoked"):
                chosen = a
                break
    if chosen is None:
        # log attempt without credential/account
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_id("hv_req_"),
            "endpoint": "create-workout",
            "account_id": None,
            "status": "UNAUTHORIZED",
            "error_code": "UNAUTHORIZED",
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _iso(now),
        })
        _save("request_logs.json", logs)
        return _err("UNAUTHORIZED", "No authenticated account context is available")

    # reset daily counter if needed and enforce quota for mutating tool
    def _parse_iso_maybe(s):
        if isinstance(s, str) and s:
            try:
                x = s
                if x.endswith("Z"):
                    x = x[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(x)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except ValueError:
                return None
        return None

    reset_at = _parse_iso_maybe(chosen.get("daily_count_reset_at"))
    if reset_at is None:
        reset_at = now.replace(hour=0, minute=0, second=0, microsecond=0) + datetime.timedelta(days=1)
        chosen["daily_count_reset_at"] = _iso(reset_at)
        chosen["daily_request_count"] = int(chosen.get("daily_request_count") or 0)
        chosen["updated_at"] = _iso(now)
        # persist
        for i, a in enumerate(accounts):
            if isinstance(a, dict) and a.get("id") == chosen.get("id"):
                accounts[i] = chosen
                break
        _save("accounts.json", accounts)
    elif now >= reset_at:
        # advance to next day boundary
        next_reset = now.replace(hour=0, minute=0, second=0, microsecond=0) + datetime.timedelta(days=1)
        chosen["daily_request_count"] = 0
        chosen["daily_count_reset_at"] = _iso(next_reset)
        chosen["updated_at"] = _iso(now)
        for i, a in enumerate(accounts):
            if isinstance(a, dict) and a.get("id") == chosen.get("id"):
                accounts[i] = chosen
                break
        _save("accounts.json", accounts)

    limit = chosen.get("daily_request_limit")
    try:
        limit = int(limit)
    except Exception:
        limit = 0
    count = chosen.get("daily_request_count")
    try:
        count = int(count)
    except Exception:
        count = 0

    # Validate inputs
    if not isinstance(title, str) or len(title.strip()) < 1:
        status_code = "VALIDATION_ERROR"
        msg = "title must be a non-empty string"
        # increment count & log
        chosen["daily_request_count"] = count + 1
        chosen["updated_at"] = _iso(now)
        for i, a in enumerate(accounts):
            if isinstance(a, dict) and a.get("id") == chosen.get("id"):
                accounts[i] = chosen
                break
        _save("accounts.json", accounts)
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({"id": _new_id("hv_req_"), "endpoint": "create-workout", "account_id": chosen.get("id"),
                     "status": status_code, "error_code": status_code, "latency_ms": int((time.time()-t0)*1000),
                     "created_at": _iso(now)})
        _save("request_logs.json", logs)
        return _err(status_code, msg)

    if privacy is None:
        privacy = "private"
    if not isinstance(privacy, str) or privacy not in ("private", "friends", "public"):
        chosen["daily_request_count"] = count + 1
        chosen["updated_at"] = _iso(now)
        for i, a in enumerate(accounts):
            if isinstance(a, dict) and a.get("id") == chosen.get("id"):
                accounts[i] = chosen
                break
        _save("accounts.json", accounts)
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({"id": _new_id("hv_req_"), "endpoint": "create-workout", "account_id": chosen.get("id"),
                     "status": "VALIDATION_ERROR", "error_code": "VALIDATION_ERROR",
                     "latency_ms": int((time.time()-t0)*1000), "created_at": _iso(now)})
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "privacy must be one of: private, friends, public")

    sdt, e = _parse_dt(started_at, "started_at")
    if e:
        chosen["daily_request_count"] = count + 1
        chosen["updated_at"] = _iso(now)
        for i, a in enumerate(accounts):
            if isinstance(a, dict) and a.get("id") == chosen.get("id"):
                accounts[i] = chosen
                break
        _save("accounts.json", accounts)
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({"id": _new_id("hv_req_"), "endpoint": "create-workout", "account_id": chosen.get("id"),
                     "status": "VALIDATION_ERROR", "error_code": "VALIDATION_ERROR",
                     "latency_ms": int((time.time()-t0)*1000), "created_at": _iso(now)})
        _save("request_logs.json", logs)
        return e
    edt, e = _parse_dt(ended_at, "ended_at")
    if e:
        chosen["daily_request_count"] = count + 1
        chosen["updated_at"] = _iso(now)
        for i, a in enumerate(accounts):
            if isinstance(a, dict) and a.get("id") == chosen.get("id"):
                accounts[i] = chosen
                break
        _save("accounts.json", accounts)
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({"id": _new_id("hv_req_"), "endpoint": "create-workout", "account_id": chosen.get("id"),
                     "status": "VALIDATION_ERROR", "error_code": "VALIDATION_ERROR",
                     "latency_ms": int((time.time()-t0)*1000), "created_at": _iso(now)})
        _save("request_logs.json", logs)
        return e

    if edt < sdt:
        chosen["daily_request_count"] = count + 1
        chosen["updated_at"] = _iso(now)
        for i, a in enumerate(accounts):
            if isinstance(a, dict) and a.get("id") == chosen.get("id"):
                accounts[i] = chosen
                break
        _save("accounts.json", accounts)
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({"id": _new_id("hv_req_"), "endpoint": "create-workout", "account_id": chosen.get("id"),
                     "status": "VALIDATION_ERROR", "error_code": "VALIDATION_ERROR",
                     "latency_ms": int((time.time()-t0)*1000), "created_at": _iso(now)})
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "ended_at must be >= started_at")

    computed_duration = int(max(0, (edt - sdt).total_seconds()))
    if duration_seconds is None:
        duration_seconds = computed_duration
    if not isinstance(duration_seconds, int) or duration_seconds < 0:
        chosen["daily_request_count"] = count + 1
        chosen["updated_at"] = _iso(now)
        for i, a in enumerate(accounts):
            if isinstance(a, dict) and a.get("id") == chosen.get("id"):
                accounts[i] = chosen
                break
        _save("accounts.json", accounts)
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({"id": _new_id("hv_req_"), "endpoint": "create-workout", "account_id": chosen.get("id"),
                     "status": "VALIDATION_ERROR", "error_code": "VALIDATION_ERROR",
                     "latency_ms": int((time.time()-t0)*1000), "created_at": _iso(now)})
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "duration_seconds must be an integer >= 0")

    if not isinstance(exercises, list) or len(exercises) < 1:
        chosen["daily_request_count"] = count + 1
        chosen["updated_at"] = _iso(now)
        for i, a in enumerate(accounts):
            if isinstance(a, dict) and a.get("id") == chosen.get("id"):
                accounts[i] = chosen
                break
        _save("accounts.json", accounts)
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({"id": _new_id("hv_req_"), "endpoint": "create-workout", "account_id": chosen.get("id"),
                     "status": "VALIDATION_ERROR", "error_code": "VALIDATION_ERROR",
                     "latency_ms": int((time.time()-t0)*1000), "created_at": _iso(now)})
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "exercises must be a non-empty array")

    ext_pat = re.compile(r"^hv_ext_[0-9A-HJKMNP-TV-Z]{10,}$")
    def _validate_set(st):
        if not isinstance(st, dict):
            return _err("VALIDATION_ERROR", "Each set must be an object")
        for k in st.keys():
            if k not in ("set_index", "reps", "weight", "duration_seconds", "distance", "rpe", "notes"):
                return _err("VALIDATION_ERROR", f"Unknown set field: {k}")
        if "set_index" in st:
            if not isinstance(st["set_index"], int) or st["set_index"] < 0:
                return _err("VALIDATION_ERROR", "set_index must be an integer >= 0")
        if "reps" in st:
            if not isinstance(st["reps"], int) or st["reps"] < 0:
                return _err("VALIDATION_ERROR", "reps must be an integer >= 0")
        if "duration_seconds" in st:
            if not isinstance(st["duration_seconds"], int) or st["duration_seconds"] < 0:
                return _err("VALIDATION_ERROR", "set duration_seconds must be an integer >= 0")
        if "weight" in st:
            if not isinstance(st["weight"], (int, float)) or st["weight"] < 0:
                return _err("VALIDATION_ERROR", "weight must be a number >= 0")
        if "distance" in st:
            if not isinstance(st["distance"], (int, float)) or st["distance"] < 0:
                return _err("VALIDATION_ERROR", "distance must be a number >= 0")
        if "rpe" in st:
            if not isinstance(st["rpe"], (int, float)) or st["rpe"] < 0 or st["rpe"] > 10:
                return _err("VALIDATION_ERROR", "rpe must be between 0 and 10")
        if "notes" in st and st["notes"] is not None and not isinstance(st["notes"], str):
            return _err("VALIDATION_ERROR", "notes must be a string")
        return None

    def _validate_ex(ex):
        if not isinstance(ex, dict):
            return _err("VALIDATION_ERROR", "Each exercise must be an object")
        for k in ex.keys():
            if k not in ("exercise_template_id", "hevy_exercise_template_id", "title", "type", "sets"):
                return _err("VALIDATION_ERROR", f"Unknown exercise field: {k}")
        sets = ex.get("sets", None)
        if not isinstance(sets, list) or len(sets) < 1:
            return _err("VALIDATION_ERROR", "Each exercise must have a non-empty sets array")
        if "exercise_template_id" in ex and ex["exercise_template_id"] is not None:
            if not isinstance(ex["exercise_template_id"], str) or not ext_pat.match(ex["exercise_template_id"]):
                return _err("VALIDATION_ERROR", "exercise_template_id is invalid")
        if "type" in ex and ex["type"] is not None:
            if not isinstance(ex["type"], str) or ex["type"] not in ("strength", "cardio", "bodyweight", "stretching", "other"):
                return _err("VALIDATION_ERROR", "exercise type is invalid")
        if "title" in ex and ex["title"] is not None and not isinstance(ex["title"], str):
            return _err("VALIDATION_ERROR", "exercise title must be a string")
        if "hevy_exercise_template_id" in ex and ex["hevy_exercise_template_id"] is not None and not isinstance(ex["hevy_exercise_template_id"], str):
            return _err("VALIDATION_ERROR", "hevy_exercise_template_id must be a string")
        for st in sets:
            e = _validate_set(st)
            if e:
                return e
        return None

    for ex in exercises:
        e = _validate_ex(ex)
        if e:
            chosen["daily_request_count"] = count + 1
            chosen["updated_at"] = _iso(now)
            for i, a in enumerate(accounts):
                if isinstance(a, dict) and a.get("id") == chosen.get("id"):
                    accounts[i] = chosen
                    break
            _save("accounts.json", accounts)
            logs = _load("request_logs.json")
            if not isinstance(logs, list): logs = []
            logs.append({"id": _new_id("hv_req_"), "endpoint": "create-workout", "account_id": chosen.get("id"),
                         "status": "VALIDATION_ERROR", "error_code": "VALIDATION_ERROR",
                         "latency_ms": int((time.time()-t0)*1000), "created_at": _iso(now)})
            _save("request_logs.json", logs)
            return e

    if description is not None and not isinstance(description, str):
        chosen["daily_request_count"] = count + 1
        chosen["updated_at"] = _iso(now)
        for i, a in enumerate(accounts):
            if isinstance(a, dict) and a.get("id") == chosen.get("id"):
                accounts[i] = chosen
                break
        _save("accounts.json", accounts)
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({"id": _new_id("hv_req_"), "endpoint": "create-workout", "account_id": chosen.get("id"),
                     "status": "VALIDATION_ERROR", "error_code": "VALIDATION_ERROR",
                     "latency_ms": int((time.time()-t0)*1000), "created_at": _iso(now)})
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "description must be a string")

    # Enforce quota now that request is validated (mutating tools rejected on quota)
    if limit > 0 and count >= limit:
        # still increment count consistently
        chosen["daily_request_count"] = count + 1
        chosen["updated_at"] = _iso(now)
        for i, a in enumerate(accounts):
            if isinstance(a, dict) and a.get("id") == chosen.get("id"):
                accounts[i] = chosen
                break
        _save("accounts.json", accounts)
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({"id": _new_id("hv_req_"), "endpoint": "create-workout", "account_id": chosen.get("id"),
                     "status": "QUOTA_EXCEEDED", "error_code": "QUOTA_EXCEEDED",
                     "latency_ms": int((time.time()-t0)*1000), "created_at": _iso(now)})
        _save("request_logs.json", logs)
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded")

    workouts = _load("workouts.json")
    if not isinstance(workouts, list):
        workouts = []

    # create upstream id placeholder (since this server is local cache); ensure uniqueness per account
    hevy_workout_id = _new_id("hevy_wkt_")
    existing = set()
    for w in workouts:
        if isinstance(w, dict) and w.get("account_id") == chosen.get("id"):
            existing.add(w.get("hevy_workout_id"))
    tries = 0
    while hevy_workout_id in existing and tries < 5:
        hevy_workout_id = _new_id("hevy_wkt_")
        tries += 1

    workout_row = {
        "id": _new_id("hv_wkt_"),
        "account_id": chosen.get("id"),
        "hevy_workout_id": hevy_workout_id,
        "title": title.strip(),
        "description": description,
        "privacy": privacy,
        "started_at": _iso(sdt),
        "ended_at": _iso(edt),
        "duration_seconds": computed_duration,  # enforce constraint based on timestamps
        "exercises": exercises,
        "source": "created_via_api",
        "status": "active",
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }

    workouts.append(workout_row)
    _save("workouts.json", workouts)

    # increment counter + persist
    chosen["daily_request_count"] = count + 1
    chosen["updated_at"] = _iso(now)
    for i, a in enumerate(accounts):
        if isinstance(a, dict) and a.get("id") == chosen.get("id"):
            accounts[i] = chosen
            break
    _save("accounts.json", accounts)

    # log call
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    logs.append({
        "id": _new_id("hv_req_"),
        "endpoint": "create-workout",
        "account_id": chosen.get("id"),
        "status": "OK",
        "error_code": None,
        "latency_ms": int((time.time() - t0) * 1000),
        "created_at": _iso(now),
    })
    _save("request_logs.json", logs)

    return {"workout": workout_row}

def update_workout(workout_id, title=None, description=None, privacy=None, started_at=None, ended_at=None, duration_seconds=None, exercises=None, **_extra):
    import json, os, datetime, time, re, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0160000" if __import__("os").path.isdir("./environment_mix/0160000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s, field):
        if not isinstance(s, str) or not s:
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO date-time string")
        try:
            x = s.strip()
            if x.endswith("Z"):
                x = x[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(x)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc), None
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} must be a valid ISO date-time")

    def _parse_iso_maybe(s):
        if isinstance(s, str) and s:
            try:
                x = s
                if x.endswith("Z"):
                    x = x[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(x)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except ValueError:
                return None
        return None

    def _base32_ulid_like(n=26):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return "".join(random.choice(alphabet) for _ in range(n))

    def _new_id(prefix):
        return f"{prefix}{_base32_ulid_like(26)}"

    # validate workout_id format
    if not isinstance(workout_id, str) or not re.match(r"^hv_wkt_[0-9A-HJKMNP-TV-Z]{10,}$", workout_id):
        # try logging with any available account context
        accounts = _load("accounts.json")
        if not isinstance(accounts, list): accounts = []
        account_id = None
        for a in accounts:
            if isinstance(a, dict) and a.get("status") == "active":
                account_id = a.get("id")
                break
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({"id": _new_id("hv_req_"), "endpoint": "update-workout", "account_id": account_id,
                     "status": "VALIDATION_ERROR", "error_code": "VALIDATION_ERROR",
                     "latency_ms": int((time.time()-t0)*1000), "created_at": _iso(now)})
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "workout_id is missing or invalid")

    # Ambient auth: choose an account that actually owns this workout id
    accounts = _load("accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    workouts = _load("workouts.json")
    if not isinstance(workouts, list):
        workouts = []

    owner_account = None
    workout_idx = None
    workout_row = None
    # prefer active account ownership
    active_ids = {a.get("id") for a in accounts if isinstance(a, dict) and a.get("status") == "active"}
    for i, w in enumerate(workouts):
        if isinstance(w, dict) and w.get("id") == workout_id and w.get("account_id") in active_ids:
            owner_account = next((a for a in accounts if isinstance(a, dict) and a.get("id") == w.get("account_id")), None)
            workout_idx = i
            workout_row = w
            break
    if workout_row is None:
        for i, w in enumerate(workouts):
            if isinstance(w, dict) and w.get("id") == workout_id:
                owner_account = next((a for a in accounts if isinstance(a, dict) and a.get("id") == w.get("account_id")), None)
                workout_idx = i
                workout_row = w
                break

    if owner_account is None or workout_row is None:
        # log attempt (if any active account exists use it; else None)
        account_id = None
        for a in accounts:
            if isinstance(a, dict) and a.get("status") == "active":
                account_id = a.get("id")
                break
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({"id": _new_id("hv_req_"), "endpoint": "update-workout", "account_id": account_id,
                     "status": "NOT_FOUND", "error_code": "NOT_FOUND",
                     "latency_ms": int((time.time()-t0)*1000), "created_at": _iso(now)})
        _save("request_logs.json", logs)
        return _err("NOT_FOUND", "Workout not found")

    # reset and enforce quota (mutating)
    reset_at = _parse_iso_maybe(owner_account.get("daily_count_reset_at"))
    if reset_at is None or now >= reset_at:
        next_reset = now.replace(hour=0, minute=0, second=0, microsecond=0) + datetime.timedelta(days=1)
        owner_account["daily_request_count"] = 0
        owner_account["daily_count_reset_at"] = _iso(next_reset)
        owner_account["updated_at"] = _iso(now)

    try:
        limit = int(owner_account.get("daily_request_limit") or 0)
    except Exception:
        limit = 0
    try:
        count = int(owner_account.get("daily_request_count") or 0)
    except Exception:
        count = 0

    # Validate provided fields
    if title is not None and (not isinstance(title, str) or len(title.strip()) < 1):
        # increment + log
        owner_account["daily_request_count"] = count + 1
        owner_account["updated_at"] = _iso(now)
        for i, a in enumerate(accounts):
            if isinstance(a, dict) and a.get("id") == owner_account.get("id"):
                accounts[i] = owner_account
                break
        _save("accounts.json", accounts)
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({"id": _new_id("hv_req_"), "endpoint": "update-workout", "account_id": owner_account.get("id"),
                     "status": "VALIDATION_ERROR", "error_code": "VALIDATION_ERROR",
                     "latency_ms": int((time.time()-t0)*1000), "created_at": _iso(now)})
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "title must be a non-empty string")

    if description is not None and not isinstance(description, str):
        owner_account["daily_request_count"] = count + 1
        owner_account["updated_at"] = _iso(now)
        for i, a in enumerate(accounts):
            if isinstance(a, dict) and a.get("id") == owner_account.get("id"):
                accounts[i] = owner_account
                break
        _save("accounts.json", accounts)
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({"id": _new_id("hv_req_"), "endpoint": "update-workout", "account_id": owner_account.get("id"),
                     "status": "VALIDATION_ERROR", "error_code": "VALIDATION_ERROR",
                     "latency_ms": int((time.time()-t0)*1000), "created_at": _iso(now)})
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "description must be a string")

    if privacy is not None and (not isinstance(privacy, str) or privacy not in ("private", "friends", "public")):
        owner_account["daily_request_count"] = count + 1
        owner_account["updated_at"] = _iso(now)
        for i, a in enumerate(accounts):
            if isinstance(a, dict) and a.get("id") == owner_account.get("id"):
                accounts[i] = owner_account
                break
        _save("accounts.json", accounts)
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({"id": _new_id("hv_req_"), "endpoint": "update-workout", "account_id": owner_account.get("id"),
                     "status": "VALIDATION_ERROR", "error_code": "VALIDATION_ERROR",
                     "latency_ms": int((time.time()-t0)*1000), "created_at": _iso(now)})
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "privacy must be one of: private, friends, public")

    if duration_seconds is not None and (not isinstance(duration_seconds, int) or duration_seconds < 0):
        owner_account["daily_request_count"] = count + 1
        owner_account["updated_at"] = _iso(now)
        for i, a in enumerate(accounts):
            if isinstance(a, dict) and a.get("id") == owner_account.get("id"):
                accounts[i] = owner_account
                break
        _save("accounts.json", accounts)
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({"id": _new_id("hv_req_"), "endpoint": "update-workout", "account_id": owner_account.get("id"),
                     "status": "VALIDATION_ERROR", "error_code": "VALIDATION_ERROR",
                     "latency_ms": int((time.time()-t0)*1000), "created_at": _iso(now)})
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "duration_seconds must be an integer >= 0")

    ext_pat = re.compile(r"^hv_ext_[0-9A-HJKMNP-TV-Z]{10,}$")
    def _validate_set(st):
        if not isinstance(st, dict):
            return _err("VALIDATION_ERROR", "Each set must be an object")
        for k in st.keys():
            if k not in ("set_index", "reps", "weight", "duration_seconds", "distance", "rpe", "notes"):
                return _err("VALIDATION_ERROR", f"Unknown set field: {k}")
        if "set_index" in st and (not isinstance(st["set_index"], int) or st["set_index"] < 0):
            return _err("VALIDATION_ERROR", "set_index must be an integer >= 0")
        if "reps" in st and (not isinstance(st["reps"], int) or st["reps"] < 0):
            return _err("VALIDATION_ERROR", "reps must be an integer >= 0")
        if "duration_seconds" in st and (not isinstance(st["duration_seconds"], int) or st["duration_seconds"] < 0):
            return _err("VALIDATION_ERROR", "set duration_seconds must be an integer >= 0")
        if "weight" in st and (not isinstance(st["weight"], (int, float)) or st["weight"] < 0):
            return _err("VALIDATION_ERROR", "weight must be a number >= 0")
        if "distance" in st and (not isinstance(st["distance"], (int, float)) or st["distance"] < 0):
            return _err("VALIDATION_ERROR", "distance must be a number >= 0")
        if "rpe" in st and (not isinstance(st["rpe"], (int, float)) or st["rpe"] < 0 or st["rpe"] > 10):
            return _err("VALIDATION_ERROR", "rpe must be between 0 and 10")
        if "notes" in st and st["notes"] is not None and not isinstance(st["notes"], str):
            return _err("VALIDATION_ERROR", "notes must be a string")
        return None

    def _validate_ex(ex):
        if not isinstance(ex, dict):
            return _err("VALIDATION_ERROR", "Each exercise must be an object")
        for k in ex.keys():
            if k not in ("exercise_template_id", "hevy_exercise_template_id", "title", "type", "sets"):
                return _err("VALIDATION_ERROR", f"Unknown exercise field: {k}")
        sets = ex.get("sets", None)
        if not isinstance(sets, list) or len(sets) < 1:
            return _err("VALIDATION_ERROR", "Each exercise must have a non-empty sets array")
        if "exercise_template_id" in ex and ex["exercise_template_id"] is not None:
            if not isinstance(ex["exercise_template_id"], str) or not ext_pat.match(ex["exercise_template_id"]):
                return _err("VALIDATION_ERROR", "exercise_template_id is invalid")
        if "type" in ex and ex["type"] is not None:
            if not isinstance(ex["type"], str) or ex["type"] not in ("strength", "cardio", "bodyweight", "stretching", "other"):
                return _err("VALIDATION_ERROR", "exercise type is invalid")
        if "title" in ex and ex["title"] is not None and not isinstance(ex["title"], str):
            return _err("VALIDATION_ERROR", "exercise title must be a string")
        if "hevy_exercise_template_id" in ex and ex["hevy_exercise_template_id"] is not None and not isinstance(ex["hevy_exercise_template_id"], str):
            return _err("VALIDATION_ERROR", "hevy_exercise_template_id must be a string")
        for st in sets:
            e = _validate_set(st)
            if e:
                return e
        return None

    if exercises is not None:
        if not isinstance(exercises, list) or len(exercises) < 1:
            owner_account["daily_request_count"] = count + 1
            owner_account["updated_at"] = _iso(now)
            for i, a in enumerate(accounts):
                if isinstance(a, dict) and a.get("id") == owner_account.get("id"):
                    accounts[i] = owner_account
                    break
            _save("accounts.json", accounts)
            logs = _load("request_logs.json")
            if not isinstance(logs, list): logs = []
            logs.append({"id": _new_id("hv_req_"), "endpoint": "update-workout", "account_id": owner_account.get("id"),
                         "status": "VALIDATION_ERROR", "error_code": "VALIDATION_ERROR",
                         "latency_ms": int((time.time()-t0)*1000), "created_at": _iso(now)})
            _save("request_logs.json", logs)
            return _err("VALIDATION_ERROR", "exercises must be a non-empty array when provided")
        for ex in exercises:
            e = _validate_ex(ex)
            if e:
                owner_account["daily_request_count"] = count + 1
                owner_account["updated_at"] = _iso(now)
                for i, a in enumerate(accounts):
                    if isinstance(a, dict) and a.get("id") == owner_account.get("id"):
                        accounts[i] = owner_account
                        break
                _save("accounts.json", accounts)
                logs = _load("request_logs.json")
                if not isinstance(logs, list): logs = []
                logs.append({"id": _new_id("hv_req_"), "endpoint": "update-workout", "account_id": owner_account.get("id"),
                             "status": "VALIDATION_ERROR", "error_code": "VALIDATION_ERROR",
                             "latency_ms": int((time.time()-t0)*1000), "created_at": _iso(now)})
                _save("request_logs.json", logs)
                return e

    # Enforce quota (mutating)
    if limit > 0 and count >= limit:
        owner_account["daily_request_count"] = count + 1
        owner_account["updated_at"] = _iso(now)
        for i, a in enumerate(accounts):
            if isinstance(a, dict) and a.get("id") == owner_account.get("id"):
                accounts[i] = owner_account
                break
        _save("accounts.json", accounts)
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({"id": _new_id("hv_req_"), "endpoint": "update-workout", "account_id": owner_account.get("id"),
                     "status": "QUOTA_EXCEEDED", "error_code": "QUOTA_EXCEEDED",
                     "latency_ms": int((time.time()-t0)*1000), "created_at": _iso(now)})
        _save("request_logs.json", logs)
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded")

    # Apply updates (allowed fields only)
    # timestamps: if one provided, validate both after merge
    cur_started = _parse_iso_maybe(workout_row.get("started_at")) or now
    cur_ended = _parse_iso_maybe(workout_row.get("ended_at")) or cur_started
    if started_at is not None:
        cur_started, e = _parse_dt(started_at, "started_at")
        if e:
            owner_account["daily_request_count"] = count + 1
            owner_account["updated_at"] = _iso(now)
            for i, a in enumerate(accounts):
                if isinstance(a, dict) and a.get("id") == owner_account.get("id"):
                    accounts[i] = owner_account
                    break
            _save("accounts.json", accounts)
            logs = _load("request_logs.json")
            if not isinstance(logs, list): logs = []
            logs.append({"id": _new_id("hv_req_"), "endpoint": "update-workout", "account_id": owner_account.get("id"),
                         "status": "VALIDATION_ERROR", "error_code": "VALIDATION_ERROR",
                         "latency_ms": int((time.time()-t0)*1000), "created_at": _iso(now)})
            _save("request_logs.json", logs)
            return e
    if ended_at is not None:
        cur_ended, e = _parse_dt(ended_at, "ended_at")
        if e:
            owner_account["daily_request_count"] = count + 1
            owner_account["updated_at"] = _iso(now)
            for i, a in enumerate(accounts):
                if isinstance(a, dict) and a.get("id") == owner_account.get("id"):
                    accounts[i] = owner_account
                    break
            _save("accounts.json", accounts)
            logs = _load("request_logs.json")
            if not isinstance(logs, list): logs = []
            logs.append({"id": _new_id("hv_req_"), "endpoint": "update-workout", "account_id": owner_account.get("id"),
                         "status": "VALIDATION_ERROR", "error_code": "VALIDATION_ERROR",
                         "latency_ms": int((time.time()-t0)*1000), "created_at": _iso(now)})
            _save("request_logs.json", logs)
            return e

    if cur_ended < cur_started:
        owner_account["daily_request_count"] = count + 1
        owner_account["updated_at"] = _iso(now)
        for i, a in enumerate(accounts):
            if isinstance(a, dict) and a.get("id") == owner_account.get("id"):
                accounts[i] = owner_account
                break
        _save("accounts.json", accounts)
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({"id": _new_id("hv_req_"), "endpoint": "update-workout", "account_id": owner_account.get("id"),
                     "status": "VALIDATION_ERROR", "error_code": "VALIDATION_ERROR",
                     "latency_ms": int((time.time()-t0)*1000), "created_at": _iso(now)})
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "ended_at must be >= started_at")

    if title is not None:
        workout_row["title"] = title.strip()
    if description is not None:
        workout_row["description"] = description
    if privacy is not None:
        workout_row["privacy"] = privacy
    if started_at is not None:
        workout_row["started_at"] = _iso(cur_started)
    if ended_at is not None:
        workout_row["ended_at"] = _iso(cur_ended)

    # enforce duration constraint: always recompute from timestamps
    workout_row["duration_seconds"] = int(max(0, (cur_ended - cur_started).total_seconds()))
    # duration_seconds param is validated but ignored for storage because schema requires computed value

    if exercises is not None:
        workout_row["exercises"] = exercises

    workout_row["source"] = "updated_via_api"
    workout_row["updated_at"] = _iso(now)

    workouts[workout_idx] = workout_row
    _save("workouts.json", workouts)

    # append workout_event
    events = _load("workout_events.json")
    if not isinstance(events, list):
        events = []
    events.append({
        "id": _new_id("hv_wke_"),
        "account_id": owner_account.get("id"),
        "workout_id": workout_row.get("id"),
        "hevy_workout_id": workout_row.get("hevy_workout_id"),
        "event_type": "updated",
        "effective_at": _iso(now),
        "payload_snapshot": {
            "workout_id": workout_row.get("id"),
            "hevy_workout_id": workout_row.get("hevy_workout_id"),
        },
        "created_at": _iso(now),
        "updated_at": _iso(now),
    })
    _save("workout_events.json", events)

    # increment + persist account counter
    owner_account["daily_request_count"] = count + 1
    owner_account["updated_at"] = _iso(now)
    for i, a in enumerate(accounts):
        if isinstance(a, dict) and a.get("id") == owner_account.get("id"):
            accounts[i] = owner_account
            break
    _save("accounts.json", accounts)

    # log call
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    logs.append({
        "id": _new_id("hv_req_"),
        "endpoint": "update-workout",
        "account_id": owner_account.get("id"),
        "status": "OK",
        "error_code": None,
        "latency_ms": int((time.time() - t0) * 1000),
        "created_at": _iso(now),
    })
    _save("request_logs.json", logs)

    return {"workout": workout_row}

def get_routines(limit=None, cursor=None, folder_id=None, status=None, is_default=None, **_extra):
    import json, os, datetime, time, base64, re

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0160000" if __import__("os").path.isdir("./environment_mix/0160000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if not isinstance(dt, datetime.datetime):
            dt = _now_utc()
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s):
        if not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    def _b64d(s):
        pad = "=" * (-len(s) % 4)
        return base64.urlsafe_b64decode((s + pad).encode("ascii"))

    def _b64e(b):
        return base64.urlsafe_b64encode(b).decode("ascii").rstrip("=")

    def _encode_cursor(offset):
        raw = json.dumps({"offset": offset}, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return _b64e(raw)

    def _decode_cursor(cur):
        # be tolerant: treat malformed/unknown opaque cursor as offset 0
        if cur is None:
            return 0
        if not isinstance(cur, str) or not cur.strip():
            return 0
        try:
            obj = json.loads(_b64d(cur.strip()).decode("utf-8"))
            off = obj.get("offset", 0)
            if isinstance(off, int) and off >= 0:
                return off
            return 0
        except Exception:
            return 0

    def _ensure_request_log_file():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            try:
                with open(path, "w", encoding="utf-8") as f:
                    json.dump([], f)
            except Exception:
                return False
        return True

    def _log(account_id, endpoint, status_text, error_code=None):
        if not _ensure_request_log_file():
            return
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": "hv_req_" + str(int(time.time() * 1000)),
                "account_id": account_id,
                "endpoint": endpoint,
                "status": status_text,
                "error_code": error_code,
                "latency_ms": int((time.time() - _t0) * 1000),
                "timestamp": _iso(_now_utc()),
            }
        )
        _save("request_logs.json", logs)

    def _select_account():
        accounts = _load("accounts.json")
        if isinstance(accounts, dict) and "rows" in accounts:
            accounts = accounts.get("rows", [])
        if not isinstance(accounts, list):
            return None
        for a in accounts:
            if isinstance(a, dict) and a.get("status") == "active":
                return a
        for a in accounts:
            if isinstance(a, dict):
                return a
        return None

    def _reset_daily_if_needed(acct, now):
        reset_at = _parse_rfc3339(acct.get("daily_count_reset_at") or "")
        if reset_at is None or now >= reset_at:
            nxt = (now + datetime.timedelta(days=1)).replace(hour=0, minute=0, second=0, microsecond=0)
            acct["daily_request_count"] = 0
            acct["daily_count_reset_at"] = _iso(nxt)

    # Validate limit but accept 0 as "default"
    if limit is None:
        limit = 25
    if not isinstance(limit, int):
        acct = _select_account()
        _log(acct["id"] if acct else None, "get-routines", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer", field="limit")
    if limit == 0:
        limit = 25
    if limit < 1 or limit > 100:
        acct = _select_account()
        _log(acct["id"] if acct else None, "get-routines", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be between 1 and 100", field="limit")

    if folder_id is not None:
        if not isinstance(folder_id, str) or not re.match(r"^hv_rfd_[0-9A-HJKMNP-TV-Z]{10,}$", folder_id):
            acct = _select_account()
            _log(acct["id"] if acct else None, "get-routines", "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "folder_id must be an internal folder id like hv_rfd_...", field="folder_id")

    if status is not None and status not in ("active", "archived", "deleted"):
        acct = _select_account()
        _log(acct["id"] if acct else None, "get-routines", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be one of: active, archived, deleted", field="status")

    if is_default is not None and not isinstance(is_default, bool):
        acct = _select_account()
        _log(acct["id"] if acct else None, "get-routines", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "is_default must be a boolean", field="is_default")

    acct = _select_account()
    if not acct:
        _log(None, "get-routines", "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authenticated account context available")

    # increment daily count for reads
    now = _now_utc()
    accounts = _load("accounts.json")
    if isinstance(accounts, dict) and "rows" in accounts:
        acc_rows = accounts.get("rows", [])
        wrapper = True
    else:
        acc_rows = accounts if isinstance(accounts, list) else []
        wrapper = False
    acct_row = None
    for a in acc_rows:
        if isinstance(a, dict) and a.get("id") == acct.get("id"):
            acct_row = a
            break
    if acct_row is None:
        _log(acct.get("id"), "get-routines", "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Account context not found")
    _reset_daily_if_needed(acct_row, now)
    acct_row["daily_request_count"] = int(acct_row.get("daily_request_count") or 0) + 1
    acct_row["updated_at"] = _iso(now)
    if wrapper:
        accounts["rows"] = acc_rows
        _save("accounts.json", accounts)
    else:
        _save("accounts.json", acc_rows)

    routines = _load("routines.json")
    if isinstance(routines, dict) and "rows" in routines:
        routines = routines.get("rows", [])
    if not isinstance(routines, list):
        routines = []

    def _sort_key(r):
        # newest to oldest using created_at (no upstream timestamp field in schema)
        dt = _parse_rfc3339(r.get("created_at") or "")
        return dt or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

    rows = []
    for r in routines:
        if not isinstance(r, dict):
            continue
        if r.get("account_id") != acct_row.get("id"):
            continue
        if folder_id is not None and r.get("folder_id") != folder_id:
            continue
        if status is not None and r.get("status") != status:
            continue
        if is_default is not None and bool(r.get("is_default")) != is_default:
            continue
        rows.append(r)

    rows.sort(key=_sort_key, reverse=True)

    offset = _decode_cursor(cursor)
    page = rows[offset : offset + limit]
    next_off = offset + len(page)
    has_more = next_off < len(rows)
    next_cursor = _encode_cursor(next_off) if has_more else None

    _log(acct_row.get("id"), "get-routines", "ok", None)
    return {"routines": page, "total": len(rows), "has_more": has_more, "next_cursor": next_cursor}

def get_routine(routine_id=None, hevy_routine_id=None, **_extra):
    import json, os, datetime, time, re

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0160000" if __import__("os").path.isdir("./environment_mix/0160000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if not isinstance(dt, datetime.datetime):
            dt = _now_utc()
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _ensure_request_log_file():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            try:
                with open(path, "w", encoding="utf-8") as f:
                    json.dump([], f)
            except Exception:
                return False
        return True

    def _log(account_id, endpoint, status_text, error_code=None):
        if not _ensure_request_log_file():
            return
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": "hv_req_" + str(int(time.time() * 1000)),
                "account_id": account_id,
                "endpoint": endpoint,
                "status": status_text,
                "error_code": error_code,
                "latency_ms": int((time.time() - _t0) * 1000),
                "timestamp": _iso(_now_utc()),
            }
        )
        _save("request_logs.json", logs)

    def _select_account():
        accounts = _load("accounts.json")
        if isinstance(accounts, dict) and "rows" in accounts:
            accounts = accounts.get("rows", [])
        if not isinstance(accounts, list):
            return None
        for a in accounts:
            if isinstance(a, dict) and a.get("status") == "active":
                return a
        for a in accounts:
            if isinstance(a, dict):
                return a
        return None

    if routine_id is None and hevy_routine_id is None:
        acct = _select_account()
        _log(acct["id"] if acct else None, "get-routine", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Either routine_id or hevy_routine_id is required")

    if routine_id is not None:
        # be tolerant: accept even if it doesn't match strict pattern; only require string
        if not isinstance(routine_id, str) or not routine_id.strip():
            acct = _select_account()
            _log(acct["id"] if acct else None, "get-routine", "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "routine_id must be a string", field="routine_id")
        # If provided and looks like hv_rtn_..., okay; if caller passed something else, still try lookup by id.

    if hevy_routine_id is not None and (not isinstance(hevy_routine_id, str) or not hevy_routine_id.strip()):
        acct = _select_account()
        _log(acct["id"] if acct else None, "get-routine", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "hevy_routine_id must be a string", field="hevy_routine_id")

    acct = _select_account()
    if not acct:
        _log(None, "get-routine", "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authenticated account context available")

    # increment daily count for reads
    now = _now_utc()
    accounts = _load("accounts.json")
    if isinstance(accounts, dict) and "rows" in accounts:
        acc_rows = accounts.get("rows", [])
        wrapper = True
    else:
        acc_rows = accounts if isinstance(accounts, list) else []
        wrapper = False
    acct_row = None
    for a in acc_rows:
        if isinstance(a, dict) and a.get("id") == acct.get("id"):
            acct_row = a
            break
    if acct_row is None:
        _log(acct.get("id"), "get-routine", "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Account context not found")
    # reset if needed (best-effort)
    try:
        reset_at = acct_row.get("daily_count_reset_at")
        if isinstance(reset_at, str) and reset_at.endswith("Z"):
            reset_at = reset_at[:-1] + "+00:00"
        ra = datetime.datetime.fromisoformat(reset_at) if isinstance(reset_at, str) else None
        if ra is None or ra.tzinfo is None:
            ra = None
    except Exception:
        ra = None
    if ra is None or now >= ra:
        nxt = (now + datetime.timedelta(days=1)).replace(hour=0, minute=0, second=0, microsecond=0)
        acct_row["daily_request_count"] = 0
        acct_row["daily_count_reset_at"] = _iso(nxt)
    acct_row["daily_request_count"] = int(acct_row.get("daily_request_count") or 0) + 1
    acct_row["updated_at"] = _iso(now)
    if wrapper:
        accounts["rows"] = acc_rows
        _save("accounts.json", accounts)
    else:
        _save("accounts.json", acc_rows)

    routines = _load("routines.json")
    if isinstance(routines, dict) and "rows" in routines:
        routines = routines.get("rows", [])
    if not isinstance(routines, list):
        routines = []

    found = None
    for r in routines:
        if not isinstance(r, dict):
            continue
        if r.get("account_id") != acct_row.get("id"):
            continue
        if routine_id is not None and r.get("id") == routine_id:
            found = r
            break
        if hevy_routine_id is not None and r.get("hevy_routine_id") == hevy_routine_id:
            found = r
            break

    if not found:
        _log(acct_row.get("id"), "get-routine", "error", "NOT_FOUND")
        return _err("NOT_FOUND", "Routine not found")

    _log(acct_row.get("id"), "get-routine", "ok", None)
    return {"routine": found}

def create_routine(title, exercise_configs, notes=None, folder_id=None, is_default=None, **_extra):
    import json, os, datetime, re, time, random

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0160000" if __import__("os").path.isdir("./environment_mix/0160000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _b32_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "".join(random.choice(alphabet) for _ in range(16))

    # --- ambient auth: choose any active account able to serve request ---
    accounts = _load("accounts.json")
    acct = None
    for a in accounts:
        if a.get("status") == "active":
            acct = a
            break
    if not acct:
        # log attempt if possible (no accounts -> nowhere to log)
        return _err("UNAUTHORIZED", "No active account available.")

    # daily quota reset/advance + enforcement
    now_iso = _now()
    reset_at = _parse_dt(acct.get("daily_count_reset_at")) if isinstance(acct.get("daily_count_reset_at"), str) else None
    now_dt = _parse_dt(now_iso)
    if not reset_at:
        reset_at = now_dt
    # if past reset, reset count and set next reset to next UTC midnight
    if now_dt and reset_at and now_dt >= reset_at:
        acct["daily_request_count"] = 0
        next_midnight = (now_dt.astimezone(datetime.timezone.utc).replace(hour=0, minute=0, second=0, microsecond=0) +
                         datetime.timedelta(days=1))
        acct["daily_count_reset_at"] = next_midnight.isoformat()

    limit = acct.get("daily_request_limit", 0)
    count = acct.get("daily_request_count", 0)
    if not isinstance(limit, int) or limit < 0:
        return _err("VALIDATION_ERROR", "Account daily_request_limit invalid.")
    if not isinstance(count, int) or count < 0:
        return _err("VALIDATION_ERROR", "Account daily_request_count invalid.")
    if limit > 0 and count >= limit:
        # still increment consistently
        acct["daily_request_count"] = count + 1
        acct["updated_at"] = now_iso
        for i, a in enumerate(accounts):
            if a.get("id") == acct.get("id"):
                accounts[i] = acct
                break
        _save("accounts.json", accounts)
        return _err("QUOTA_EXCEEDED", "Daily request limit exceeded.", daily_request_limit=limit, daily_request_count=acct["daily_request_count"])

    # --- validate inputs ---
    if not isinstance(title, str):
        acct["daily_request_count"] = count + 1
        acct["updated_at"] = now_iso
        for i, a in enumerate(accounts):
            if a.get("id") == acct.get("id"):
                accounts[i] = acct
                break
        _save("accounts.json", accounts)
        return _err("VALIDATION_ERROR", "title must be a string.")
    if title.strip() == "":
        acct["daily_request_count"] = count + 1
        acct["updated_at"] = now_iso
        for i, a in enumerate(accounts):
            if a.get("id") == acct.get("id"):
                accounts[i] = acct
                break
        _save("accounts.json", accounts)
        return _err("VALIDATION_ERROR", "title must not be empty.")

    if notes is not None and not isinstance(notes, str):
        acct["daily_request_count"] = count + 1
        acct["updated_at"] = now_iso
        for i, a in enumerate(accounts):
            if a.get("id") == acct.get("id"):
                accounts[i] = acct
                break
        _save("accounts.json", accounts)
        return _err("VALIDATION_ERROR", "notes must be a string if provided.")

    if folder_id is not None:
        if not isinstance(folder_id, str):
            acct["daily_request_count"] = count + 1
            acct["updated_at"] = now_iso
            for i, a in enumerate(accounts):
                if a.get("id") == acct.get("id"):
                    accounts[i] = acct
                    break
            _save("accounts.json", accounts)
            return _err("VALIDATION_ERROR", "folder_id must be a string if provided.")
        if not re.match(r"^hv_rfd_[0-9A-HJKMNP-TV-Z]{10,}$", folder_id):
            acct["daily_request_count"] = count + 1
            acct["updated_at"] = now_iso
            for i, a in enumerate(accounts):
                if a.get("id") == acct.get("id"):
                    accounts[i] = acct
                    break
            _save("accounts.json", accounts)
            return _err("VALIDATION_ERROR", "folder_id has invalid format.")

    if is_default is not None and not isinstance(is_default, bool):
        acct["daily_request_count"] = count + 1
        acct["updated_at"] = now_iso
        for i, a in enumerate(accounts):
            if a.get("id") == acct.get("id"):
                accounts[i] = acct
                break
        _save("accounts.json", accounts)
        return _err("VALIDATION_ERROR", "is_default must be a boolean if provided.")

    if not isinstance(exercise_configs, list) or len(exercise_configs) < 1:
        acct["daily_request_count"] = count + 1
        acct["updated_at"] = now_iso
        for i, a in enumerate(accounts):
            if a.get("id") == acct.get("id"):
                accounts[i] = acct
                break
        _save("accounts.json", accounts)
        return _err("VALIDATION_ERROR", "exercise_configs must be a non-empty array.")

    allowed_types = {"strength", "cardio", "bodyweight", "stretching", "other"}
    allowed_set_types = {"normal", "warmup", "drop", "failure"}

    for idx, ex in enumerate(exercise_configs):
        if not isinstance(ex, dict):
            acct["daily_request_count"] = count + 1
            acct["updated_at"] = now_iso
            for i, a in enumerate(accounts):
                if a.get("id") == acct.get("id"):
                    accounts[i] = acct
                    break
            _save("accounts.json", accounts)
            return _err("VALIDATION_ERROR", f"exercise_configs[{idx}] must be an object.")
        sets = ex.get("sets")
        if not isinstance(sets, list) or len(sets) < 1:
            acct["daily_request_count"] = count + 1
            acct["updated_at"] = now_iso
            for i, a in enumerate(accounts):
                if a.get("id") == acct.get("id"):
                    accounts[i] = acct
                    break
            _save("accounts.json", accounts)
            return _err("VALIDATION_ERROR", f"exercise_configs[{idx}].sets must be a non-empty array.")
        # validate optional fields minimally per schema
        if "exercise_template_id" in ex and ex["exercise_template_id"] is not None:
            if not isinstance(ex["exercise_template_id"], str) or not re.match(r"^hv_ext_[0-9A-HJKMNP-TV-Z]{10,}$", ex["exercise_template_id"]):
                acct["daily_request_count"] = count + 1
                acct["updated_at"] = now_iso
                for i, a in enumerate(accounts):
                    if a.get("id") == acct.get("id"):
                        accounts[i] = acct
                        break
                _save("accounts.json", accounts)
                return _err("VALIDATION_ERROR", f"exercise_configs[{idx}].exercise_template_id has invalid format.")
        if "title" in ex and ex["title"] is not None and not isinstance(ex["title"], str):
            acct["daily_request_count"] = count + 1
            acct["updated_at"] = now_iso
            for i, a in enumerate(accounts):
                if a.get("id") == acct.get("id"):
                    accounts[i] = acct
                    break
            _save("accounts.json", accounts)
            return _err("VALIDATION_ERROR", f"exercise_configs[{idx}].title must be a string if provided.")
        if "type" in ex and ex["type"] is not None:
            if not isinstance(ex["type"], str) or ex["type"] not in allowed_types:
                acct["daily_request_count"] = count + 1
                acct["updated_at"] = now_iso
                for i, a in enumerate(accounts):
                    if a.get("id") == acct.get("id"):
                        accounts[i] = acct
                        break
                _save("accounts.json", accounts)
                return _err("VALIDATION_ERROR", f"exercise_configs[{idx}].type must be one of {sorted(allowed_types)}.")
        if "notes" in ex and ex["notes"] is not None and not isinstance(ex["notes"], str):
            acct["daily_request_count"] = count + 1
            acct["updated_at"] = now_iso
            for i, a in enumerate(accounts):
                if a.get("id") == acct.get("id"):
                    accounts[i] = acct
                    break
            _save("accounts.json", accounts)
            return _err("VALIDATION_ERROR", f"exercise_configs[{idx}].notes must be a string if provided.")

        for sidx, st in enumerate(sets):
            if not isinstance(st, dict):
                acct["daily_request_count"] = count + 1
                acct["updated_at"] = now_iso
                for i, a in enumerate(accounts):
                    if a.get("id") == acct.get("id"):
                        accounts[i] = acct
                        break
                _save("accounts.json", accounts)
                return _err("VALIDATION_ERROR", f"exercise_configs[{idx}].sets[{sidx}] must be an object.")
            if "set_type" in st and st["set_type"] is not None:
                if not isinstance(st["set_type"], str) or st["set_type"] not in allowed_set_types:
                    acct["daily_request_count"] = count + 1
                    acct["updated_at"] = now_iso
                    for i, a in enumerate(accounts):
                        if a.get("id") == acct.get("id"):
                            accounts[i] = acct
                            break
                    _save("accounts.json", accounts)
                    return _err("VALIDATION_ERROR", f"exercise_configs[{idx}].sets[{sidx}].set_type invalid.")
            if "reps" in st and st["reps"] is not None and (not isinstance(st["reps"], int)):
                acct["daily_request_count"] = count + 1
                acct["updated_at"] = now_iso
                for i, a in enumerate(accounts):
                    if a.get("id") == acct.get("id"):
                        accounts[i] = acct
                        break
                _save("accounts.json", accounts)
                return _err("VALIDATION_ERROR", f"exercise_configs[{idx}].sets[{sidx}].reps must be integer.")
            if "duration_seconds" in st and st["duration_seconds"] is not None and (not isinstance(st["duration_seconds"], int)):
                acct["daily_request_count"] = count + 1
                acct["updated_at"] = now_iso
                for i, a in enumerate(accounts):
                    if a.get("id") == acct.get("id"):
                        accounts[i] = acct
                        break
                _save("accounts.json", accounts)
                return _err("VALIDATION_ERROR", f"exercise_configs[{idx}].sets[{sidx}].duration_seconds must be integer.")
            for nf in ("weight", "distance", "rpe"):
                if nf in st and st[nf] is not None and not isinstance(st[nf], (int, float)):
                    acct["daily_request_count"] = count + 1
                    acct["updated_at"] = now_iso
                    for i, a in enumerate(accounts):
                        if a.get("id") == acct.get("id"):
                            accounts[i] = acct
                            break
                    _save("accounts.json", accounts)
                    return _err("VALIDATION_ERROR", f"exercise_configs[{idx}].sets[{sidx}].{nf} must be a number.")
            if "notes" in st and st["notes"] is not None and not isinstance(st["notes"], str):
                acct["daily_request_count"] = count + 1
                acct["updated_at"] = now_iso
                for i, a in enumerate(accounts):
                    if a.get("id") == acct.get("id"):
                        accounts[i] = acct
                        break
                _save("accounts.json", accounts)
                return _err("VALIDATION_ERROR", f"exercise_configs[{idx}].sets[{sidx}].notes must be a string if provided.")

    # folder validation (must exist, match account, active)
    if folder_id is not None:
        folders = _load("routine_folders.json")
        folder_row = None
        for f in folders:
            if f.get("id") == folder_id and f.get("account_id") == acct.get("id") and f.get("status") == "active":
                folder_row = f
                break
        if not folder_row:
            acct["daily_request_count"] = count + 1
            acct["updated_at"] = now_iso
            for i, a in enumerate(accounts):
                if a.get("id") == acct.get("id"):
                    accounts[i] = acct
                    break
            _save("accounts.json", accounts)
            return _err("NOT_FOUND", "folder_id not found or not accessible.")

    # --- persist routine ---
    routines = _load("routines.json")

    # unique( account_id, hevy_routine_id ) generation (use same id as upstream id)
    # since this backend does not call upstream, we generate a fresh hevy-like id and use it for both.
    for _ in range(50):
        new_id = _b32_id("hv_rtn_")
        if all(r.get("id") != new_id for r in routines) and all(r.get("hevy_routine_id") != new_id or r.get("account_id") != acct.get("id") for r in routines):
            break
    else:
        acct["daily_request_count"] = count + 1
        acct["updated_at"] = now_iso
        for i, a in enumerate(accounts):
            if a.get("id") == acct.get("id"):
                accounts[i] = acct
                break
        _save("accounts.json", accounts)
        return _err("CONFLICT", "Unable to allocate a unique routine id.")

    row = {
        "id": new_id,
        "account_id": acct.get("id"),
        "hevy_routine_id": new_id,
        "title": title,
        "notes": notes,
        "folder_id": folder_id,
        "is_default": bool(is_default) if isinstance(is_default, bool) else False,
        "exercise_configs": exercise_configs,
        "status": "active",
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    routines.append(row)
    _save("routines.json", routines)

    # increment request count after successful mutation
    acct["daily_request_count"] = count + 1
    acct["updated_at"] = now_iso
    for i, a in enumerate(accounts):
        if a.get("id") == acct.get("id"):
            accounts[i] = acct
            break
    _save("accounts.json", accounts)

    return {"routine": row}

def update_routine(routine_id, title=None, notes=None, is_default=None, exercise_configs=None, **_extra):
    import json, os, datetime, time

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0160000" if __import__("os").path.isdir("./environment_mix/0160000") else "/app/database")

    def _load(n):
