            dt = _now_utc()
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _ensure_request_log_file():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            try:
                with open(path, "w", encoding="utf-8") as f:
                    json.dump([], f)
            except Exception:
                return False
        return True

    def _log(account_id, endpoint, status_text, error_code=None):
        if not _ensure_request_log_file():
            return
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": "hv_req_" + str(int(time.time() * 1000)),
                "account_id": account_id,
                "endpoint": endpoint,
                "status": status_text,
                "error_code": error_code,
                "latency_ms": int((time.time() - _t0) * 1000),
                "timestamp": _iso(_now_utc()),
            }
        )
        _save("request_logs.json", logs)

    def _select_account():
        accounts = _load("accounts.json")
        if isinstance(accounts, dict) and "rows" in accounts:
            accounts = accounts.get("rows", [])
        if not isinstance(accounts, list):
            return None
        for a in accounts:
            if isinstance(a, dict) and a.get("status") == "active":
                return a
        for a in accounts:
            if isinstance(a, dict):
                return a
        return None

    def _reset_daily_if_needed(acct, now):
        # best-effort parse
        reset_at_s = acct.get("daily_count_reset_at")
        try:
            if isinstance(reset_at_s, str):
                ss = reset_at_s.strip()
                if ss.endswith("Z"):
                    ss = ss[:-1] + "+00:00"
                ra = datetime.datetime.fromisoformat(ss)
                if ra.tzinfo is None:
                    ra = ra.replace(tzinfo=datetime.timezone.utc)
                ra = ra.astimezone(datetime.timezone.utc)
            else:
                ra = None
        except Exception:
            ra = None
        if ra is None or now >= ra:
            nxt = (now + datetime.timedelta(days=1)).replace(hour=0, minute=0, second=0, microsecond=0)
            acct["daily_request_count"] = 0
            acct["daily_count_reset_at"] = _iso(nxt)

    # Validate inputs
    if not isinstance(routine_id, str) or not routine_id.strip():
        acct = _select_account()
        _log(acct["id"] if acct else None, "update-routine", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "routine_id must be a string", field="routine_id")

    if title is not None and (not isinstance(title, str)):
        acct = _select_account()
        _log(acct["id"] if acct else None, "update-routine", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "title must be a string", field="title")
    if notes is not None and (not isinstance(notes, str)):
        acct = _select_account()
        _log(acct["id"] if acct else None, "update-routine", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "notes must be a string", field="notes")
    if is_default is not None and not isinstance(is_default, bool):
        acct = _select_account()
        _log(acct["id"] if acct else None, "update-routine", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "is_default must be a boolean", field="is_default")

    if exercise_configs is not None:
        if not isinstance(exercise_configs, list) or len(exercise_configs) < 1:
            acct = _select_account()
            _log(acct["id"] if acct else None, "update-routine", "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "exercise_configs must be a non-empty array", field="exercise_configs")
        for i, ex in enumerate(exercise_configs):
            if not isinstance(ex, dict):
                acct = _select_account()
                _log(acct["id"] if acct else None, "update-routine", "error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Each exercise config must be an object", field="exercise_configs")
            sets = ex.get("sets")
            if not isinstance(sets, list) or len(sets) < 1:
                acct = _select_account()
                _log(acct["id"] if acct else None, "update-routine", "error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Each exercise config must include at least one set", field="exercise_configs")

    acct = _select_account()
    if not acct:
        _log(None, "update-routine", "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authenticated account context available")

    # Load accounts and enforce quota for mutation
    now = _now_utc()
    accounts = _load("accounts.json")
    if isinstance(accounts, dict) and "rows" in accounts:
        acc_rows = accounts.get("rows", [])
        wrapper = True
    else:
        acc_rows = accounts if isinstance(accounts, list) else []
        wrapper = False

    acct_row = None
    for a in acc_rows:
        if isinstance(a, dict) and a.get("id") == acct.get("id"):
            acct_row = a
            break
    if acct_row is None:
        _log(acct.get("id"), "update-routine", "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Account context not found")

    _reset_daily_if_needed(acct_row, now)
    limit = int(acct_row.get("daily_request_limit") or 0)
    count = int(acct_row.get("daily_request_count") or 0)
    if limit > 0 and count >= limit:
        _log(acct_row.get("id"), "update-routine", "error", "QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Daily request limit exceeded")

    routines = _load("routines.json")
    if isinstance(routines, dict) and "rows" in routines:
        routine_rows = routines.get("rows", [])
        routines_wrapper = True
    else:
        routine_rows = routines if isinstance(routines, list) else []
        routines_wrapper = False

    # Find routine by id in this account; tolerate callers passing an account id by also trying hevy id match
    target = None
    for r in routine_rows:
        if not isinstance(r, dict):
            continue
        if r.get("account_id") != acct_row.get("id"):
            continue
        if r.get("id") == routine_id:
            target = r
            break
    if target is None:
        # fallback: some callers passed account_id accidentally; pick newest routine for this account
        if routine_id == acct_row.get("id"):
            candidates = [r for r in routine_rows if isinstance(r, dict) and r.get("account_id") == acct_row.get("id")]
            if candidates:
                def _key(x):
                    try:
                        s = x.get("created_at") or ""
                        if isinstance(s, str) and s.endswith("Z"):
                            s = s[:-1] + "+00:00"
                        dt = datetime.datetime.fromisoformat(s)
                        if dt.tzinfo is None:
                            dt = dt.replace(tzinfo=datetime.timezone.utc)
                        return dt.astimezone(datetime.timezone.utc)
                    except Exception:
                        return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
                candidates.sort(key=_key, reverse=True)
                target = candidates[0]

    if target is None:
        _log(acct_row.get("id"), "update-routine", "error", "NOT_FOUND")
        return _err("NOT_FOUND", "Routine not found for this account")

    # Apply updates (folder_id changes not allowed; ignored by schema and tool)
    changed = False
    if title is not None:
        if title.strip() == "":
            _log(acct_row.get("id"), "update-routine", "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "title cannot be empty", field="title")
        if target.get("title") != title:
            target["title"] = title
            changed = True
    if notes is not None:
        if target.get("notes") != notes:
            target["notes"] = notes
            changed = True
    if is_default is not None:
        if bool(target.get("is_default")) != is_default:
            target["is_default"] = is_default
            changed = True
    if exercise_configs is not None:
        target["exercise_configs"] = exercise_configs
        changed = True

    if not changed:
        # idempotent: still count as a mutation attempt? Real APIs often do.
        acct_row["daily_request_count"] = count + 1
        acct_row["updated_at"] = _iso(now)
        if wrapper:
            accounts["rows"] = acc_rows
            _save("accounts.json", accounts)
        else:
            _save("accounts.json", acc_rows)
        _log(acct_row.get("id"), "update-routine", "ok", None)
        return {"routine": target}

    target["updated_at"] = _iso(now)

    # persist routines
    if routines_wrapper:
        routines["rows"] = routine_rows
        _save("routines.json", routines)
    else:
        _save("routines.json", routine_rows)

    # increment quota counter and persist accounts
    acct_row["daily_request_count"] = count + 1
    acct_row["updated_at"] = _iso(now)
    if wrapper:
        accounts["rows"] = acc_rows
        _save("accounts.json", accounts)
    else:
        _save("accounts.json", acc_rows)

    _log(acct_row.get("id"), "update-routine", "ok", None)
    return {"routine": target}

def get_exercise_templates(limit=None, cursor=None, type=None, is_default=None, status=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, base64

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0160000" if __import__("os").path.isdir("./environment_mix/0160000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if not isinstance(dt, datetime.datetime):
            dt = _now_utc()
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    def _b64d(s):
        pad = "=" * (-len(s) % 4)
        return base64.urlsafe_b64decode((s + pad).encode("ascii"))

    def _b64e(b):
        return base64.urlsafe_b64encode(b).decode("ascii").rstrip("=")

    def _encode_cursor(offset):
        raw = json.dumps({"offset": offset}, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return _b64e(raw)

    def _decode_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str) or not cur.strip():
            return 0
        try:
            obj = json.loads(_b64d(cur.strip()).decode("utf-8"))
            off = obj.get("offset", 0)
            if isinstance(off, int) and off >= 0:
                return off
            return 0
        except Exception:
            return 0

    def _ensure_request_log_file():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            try:
                with open(path, "w", encoding="utf-8") as f:
                    json.dump([], f)
            except Exception:
                return False
        return True

    def _log(account_id, endpoint, status_text, error_code=None):
        if not _ensure_request_log_file():
            return
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": "hv_req_" + str(int(time.time() * 1000)),
                "account_id": account_id,
                "endpoint": endpoint,
                "status": status_text,
                "error_code": error_code,
                "latency_ms": int((time.time() - _t0) * 1000),
                "timestamp": _iso(_now_utc()),
            }
        )
        _save("request_logs.json", logs)

    def _select_account():
        accounts = _load("accounts.json")
        if isinstance(accounts, dict) and "rows" in accounts:
            accounts = accounts.get("rows", [])
        if not isinstance(accounts, list):
            return None
        for a in accounts:
            if isinstance(a, dict) and a.get("status") == "active":
                return a
        for a in accounts:
            if isinstance(a, dict):
                return a
        return None

    # limit: clamp to 100, accept 0 as default
    if limit is None:
        limit = 25
    if not isinstance(limit, int):
        acct = _select_account()
        _log(acct["id"] if acct else None, "get-exercise-templates", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer", field="limit")
    if limit == 0:
        limit = 25
    if limit < 1:
        acct = _select_account()
        _log(acct["id"] if acct else None, "get-exercise-templates", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be between 1 and 100", field="limit")
    if limit > 100:
        limit = 100

    if type is not None and type not in ("strength", "cardio", "bodyweight", "stretching", "other"):
        acct = _select_account()
        _log(acct["id"] if acct else None, "get-exercise-templates", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "type must be one of: strength, cardio, bodyweight, stretching, other", field="type")
    if status is not None and status not in ("active", "deleted"):
        acct = _select_account()
        _log(acct["id"] if acct else None, "get-exercise-templates", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be one of: active, deleted", field="status")
    if is_default is not None and not isinstance(is_default, bool):
        acct = _select_account()
        _log(acct["id"] if acct else None, "get-exercise-templates", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "is_default must be a boolean", field="is_default")
    if sort is not None and sort not in ("title", "created_at", "updated_at"):
        acct = _select_account()
        _log(acct["id"] if acct else None, "get-exercise-templates", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sort must be one of: title, created_at, updated_at", field="sort")
    if order is not None and order not in ("asc", "desc"):
        acct = _select_account()
        _log(acct["id"] if acct else None, "get-exercise-templates", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "order must be one of: asc, desc", field="order")

    acct = _select_account()
    if not acct:
        _log(None, "get-exercise-templates", "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authenticated account context available")

    # increment daily count for reads
    now = _now_utc()
    accounts = _load("accounts.json")
    if isinstance(accounts, dict) and "rows" in accounts:
        acc_rows = accounts.get("rows", [])
        wrapper = True
    else:
        acc_rows = accounts if isinstance(accounts, list) else []
        wrapper = False
    acct_row = None
    for a in acc_rows:
        if isinstance(a, dict) and a.get("id") == acct.get("id"):
            acct_row = a
            break
    if acct_row is None:
        _log(acct.get("id"), "get-exercise-templates", "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Account context not found")
    # reset daily if needed (best-effort)
    ra = _parse_dt(acct_row.get("daily_count_reset_at") or "")
    if ra is None or now >= ra:
        nxt = (now + datetime.timedelta(days=1)).replace(hour=0, minute=0, second=0, microsecond=0)
        acct_row["daily_request_count"] = 0
        acct_row["daily_count_reset_at"] = _iso(nxt)
    acct_row["daily_request_count"] = int(acct_row.get("daily_request_count") or 0) + 1
    acct_row["updated_at"] = _iso(now)
    if wrapper:
        accounts["rows"] = acc_rows
        _save("accounts.json", accounts)
    else:
        _save("accounts.json", acc_rows)

    templ = _load("exercise_templates.json")
    if isinstance(templ, dict) and "rows" in templ:
        templ = templ.get("rows", [])
    if not isinstance(templ, list):
        templ = []

    rows = []
    for t in templ:
        if not isinstance(t, dict):
            continue
        if t.get("account_id") != acct_row.get("id"):
            continue
        if type is not None and t.get("type") != type:
            continue
        if status is not None and t.get("status") != status:
            continue
        if is_default is not None and bool(t.get("is_default")) != is_default:
            continue
        rows.append(t)

    # default order: newest to oldest (updated_at fallback created_at)
    if sort is None:
        def k(x):
            return _parse_dt(x.get("updated_at") or x.get("created_at") or "") or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        rows.sort(key=k, reverse=True)
    else:
        if sort == "title":
            rows.sort(key=lambda x: (x.get("title") or "").lower())
        else:
            rows.sort(key=lambda x: _parse_dt(x.get(sort) or "") or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc))
        if order == "desc":
            rows.reverse()
        if order is None and sort != "title":
            rows.reverse()

    offset = _decode_cursor(cursor)
    page = rows[offset : offset + limit]
    next_off = offset + len(page)
    has_more = next_off < len(rows)
    next_cursor = _encode_cursor(next_off) if has_more else None

    _log(acct_row.get("id"), "get-exercise-templates", "ok", None)
    return {"exercise_templates": page, "total": len(rows), "has_more": has_more, "next_cursor": next_cursor}

def get_exercise_template(exercise_template_id, **_extra):
