                "error_code": error_code,
                "latency_ms": int((time.time() - _t0) * 1000),
                "timestamp": _iso(_now_utc()),
            }
        )
        _save("request_logs.json", logs)

    def _parse_dt(s):
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _reset_and_increment_daily(accounts, account_row):
        # daily_request_count resets at daily_count_reset_at (inclusive) and increments on every call.
        now = _now_utc()
        reset_at = _parse_dt(account_row.get("daily_count_reset_at"))
        if reset_at is None:
            # If malformed, reset now+24h (defensive)
            reset_at = now
        if now >= reset_at:
            account_row["daily_request_count"] = 0
            account_row["daily_count_reset_at"] = _iso(now + datetime.timedelta(days=1))
        # increment
        cnt = account_row.get("daily_request_count")
        if not isinstance(cnt, int) or cnt < 0:
            cnt = 0
        account_row["daily_request_count"] = cnt + 1
        account_row["updated_at"] = _iso(now)
        return accounts

    endpoint = "get-exercise-template"

    # Validate input: accept both canonical hv_ext_... ULID and legacy "ext_*" ids seen in datastore/callers.
    if not isinstance(exercise_template_id, str) or not exercise_template_id.strip():
        err = _err("VALIDATION_ERROR", "exercise_template_id is required", field="exercise_template_id")
        _log(None, endpoint, "error", err["error"]["code"])
