        err = _err(
            "VALIDATION_ERROR",
            "exercise_template_id must match '^hv_ext_[0-9A-HJKMNP-TV-Z]{10,}$' (or legacy 'ext_*' id)",
            field="exercise_template_id",
        )
        _log(None, endpoint, "error", err["error"]["code"])
        return err

    accounts = _unwrap_rows(_load("accounts.json"))
    templates = _unwrap_rows(_load("exercise_templates.json"))

    # Ambient auth resolution: pick an ACTIVE account that can actually see the requested template.
    # (Search for a working combination instead of taking the first row.)
    template_row = None
    owning_account = None

    # First find the template by id (unique), then resolve account context.
    for t in templates:
        if isinstance(t, dict) and t.get("id") == exercise_template_id:
            template_row = t
            break

    if template_row is None:
        # still log a call; account context unknown
        _log(None, endpoint, "ok", None)
        return {
            "data": None,
            "meta": {"found": False},
        }

    acct_id = template_row.get("account_id")
    if not isinstance(acct_id, str) or not acct_id:
        err = _err("UNAUTHORIZED", "No account context available for this exercise template")
        _log(None, endpoint, "error", err["error"]["code"])
        return err

    for a in accounts:
        if isinstance(a, dict) and a.get("id") == acct_id:
            owning_account = a
            break

    if owning_account is None:
        err = _err("UNAUTHORIZED", "No authenticated account can access this exercise template")
        _log(None, endpoint, "error", err["error"]["code"])
        return err

    if owning_account.get("status") != "active":
        err = _err("UNAUTHORIZED", "Account is not active")
        _log(owning_account.get("id"), endpoint, "error", err["error"]["code"])
        return err

    # Quota policy: reads are allowed but must increment daily_request_count consistently.
    # Enforce quota on reads? Policy says may be allowed; we allow but still increment.
    try:
        accounts = _reset_and_increment_daily(accounts, owning_account)
        _save("accounts.json", accounts)
    except Exception:
        err = _err("CONFLICT", "Failed to persist account usage counters")
        _log(owning_account.get("id"), endpoint, "error", err["error"]["code"])
        return err

    _log(owning_account.get("id"), endpoint, "ok", None)

    # Visibility: only templates owned by this account are visible (already ensured).
    return {
        "data": template_row,
        "meta": {"found": True},
    }

def get_routine_folders(limit=None, cursor=None, status=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, base64

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0160000" if __import__("os").path.isdir("./environment_mix/0160000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if not isinstance(dt, datetime.datetime):
            dt = _now_utc()
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    def _b64d(s):
        pad = "=" * (-len(s) % 4)
        return base64.urlsafe_b64decode((s + pad).encode("ascii"))

    def _b64e(b):
        return base64.urlsafe_b64encode(b).decode("ascii").rstrip("=")

    def _encode_cursor(offset):
        raw = json.dumps({"offset": offset}, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return _b64e(raw)

    def _decode_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str) or not cur.strip():
            return 0
        try:
            obj = json.loads(_b64d(cur.strip()).decode("utf-8"))
            off = obj.get("offset", 0)
            if isinstance(off, int) and off >= 0:
                return off
            return 0
        except Exception:
            return 0

    def _ensure_request_log_file():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            try:
                with open(path, "w", encoding="utf-8") as f:
                    json.dump([], f)
            except Exception:
                return False
        return True

    def _log(account_id, endpoint, status_text, error_code=None):
        if not _ensure_request_log_file():
            return
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": "hv_req_" + str(int(time.time() * 1000)),
                "account_id": account_id,
                "endpoint": endpoint,
                "status": status_text,
                "error_code": error_code,
                "latency_ms": int((time.time() - _t0) * 1000),
                "timestamp": _iso(_now_utc()),
            }
        )
        _save("request_logs.json", logs)

    def _select_account():
        accounts = _load("accounts.json")
        if isinstance(accounts, dict) and "rows" in accounts:
            accounts = accounts.get("rows", [])
        if not isinstance(accounts, list):
            return None
        for a in accounts:
            if isinstance(a, dict) and a.get("status") == "active":
                return a
        for a in accounts:
            if isinstance(a, dict):
                return a
        return None

    # limit validation; accept 0 as default
    if limit is None:
        limit = 25
    if not isinstance(limit, int):
        acct = _select_account()
        _log(acct["id"] if acct else None, "get-routine-folders", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer", field="limit")
    if limit == 0:
        limit = 25
    if limit < 1 or limit > 100:
        acct = _select_account()
        _log(acct["id"] if acct else None, "get-routine-folders", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be between 1 and 100", field="limit")

    if status is not None and status not in ("active", "deleted"):
        acct = _select_account()
        _log(acct["id"] if acct else None, "get-routine-folders", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be one of: active, deleted", field="status")
    if sort is not None and sort not in ("index", "title", "created_at", "updated_at"):
        acct = _select_account()
        _log(acct["id"] if acct else None, "get-routine-folders", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sort must be one of: index, title, created_at, updated_at", field="sort")
    if order is not None and order not in ("asc", "desc"):
        acct = _select_account()
        _log(acct["id"] if acct else None, "get-routine-folders", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "order must be one of: asc, desc", field="order")

    acct = _select_account()
    if not acct:
        _log(None, "get-routine-folders", "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authenticated account context available")

    # increment daily count for reads
    now = _now_utc()
    accounts = _load("accounts.json")
    if isinstance(accounts, dict) and "rows" in accounts:
        acc_rows = accounts.get("rows", [])
        wrapper = True
    else:
        acc_rows = accounts if isinstance(accounts, list) else []
        wrapper = False
    acct_row = None
    for a in acc_rows:
        if isinstance(a, dict) and a.get("id") == acct.get("id"):
            acct_row = a
            break
    if acct_row is None:
        _log(acct.get("id"), "get-routine-folders", "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Account context not found")
    acct_row["daily_request_count"] = int(acct_row.get("daily_request_count") or 0) + 1
    acct_row["updated_at"] = _iso(now)
    if wrapper:
        accounts["rows"] = acc_rows
        _save("accounts.json", accounts)
    else:
        _save("accounts.json", acc_rows)

    folders = _load("routine_folders.json")
    if isinstance(folders, dict) and "rows" in folders:
        folders = folders.get("rows", [])
    if not isinstance(folders, list):
        folders = []

    rows = []
    for f in folders:
        if not isinstance(f, dict):
            continue
        if f.get("account_id") != acct_row.get("id"):
            continue
        if status is not None and f.get("status") != status:
            continue
        rows.append(f)

    # Default order: newest to oldest (created_at); but folders often prefer index asc.
    if sort is None:
        rows.sort(key=lambda x: (_parse_dt(x.get("created_at") or "") or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)), reverse=True)
    else:
        if sort == "title":
            rows.sort(key=lambda x: (x.get("title") or "").lower())
        elif sort == "index":
            rows.sort(key=lambda x: int(x.get("index") or 0))
        else:
            rows.sort(key=lambda x: _parse_dt(x.get(sort) or "") or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc))
        if order == "desc":
            rows.reverse()
        if order is None and sort in ("created_at", "updated_at"):
            rows.reverse()

    offset = _decode_cursor(cursor)
    page = rows[offset : offset + limit]
    next_off = offset + len(page)
    has_more = next_off < len(rows)
    next_cursor = _encode_cursor(next_off) if has_more else None

    _log(acct_row.get("id"), "get-routine-folders", "ok", None)
    return {"routine_folders": page, "total": len(rows), "has_more": has_more, "next_cursor": next_cursor}

def get_routine_folder(folder_id, **_extra):
    import json, os, datetime, time, re, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0160000" if __import__("os").path.isdir("./environment_mix/0160000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _reset_daily_if_needed(acct, now_dt):
        reset_at = _parse_dt(acct.get("daily_count_reset_at"))
        if reset_at is None:
            acct["daily_count_reset_at"] = (now_dt + datetime.timedelta(days=1)).isoformat()
            acct["daily_request_count"] = int(acct.get("daily_request_count") or 0)
            return True
        if reset_at.tzinfo is None:
            reset_at = reset_at.replace(tzinfo=datetime.timezone.utc)
        if now_dt >= reset_at:
            acct["daily_request_count"] = 0
            acct["daily_count_reset_at"] = (now_dt + datetime.timedelta(days=1)).isoformat()
            return True
        return False

    t0 = time.time()
    endpoint = "get-routine-folder"

    accounts = _load("accounts.json")
    routine_folders = _load("routine_folders.json")
    request_logs = _load("request_logs.json")  # optional file

    def _log(account_id, status_code, error_code=None, error_message=None):
        nonlocal request_logs
        try:
            now = _now_iso()
            row = {
                "id": "req_" + hashlib.sha256(f"{now}:{endpoint}:{account_id}:{time.time_ns()}".encode("utf-8")).hexdigest()[:24],
                "endpoint": endpoint,
                "account_id": account_id,
                "timestamp": now,
                "status": status_code,
                "latency_ms": int((time.time() - t0) * 1000),
            }
            if error_code:
                row["error_code"] = error_code
            if error_message:
                row["error_message"] = error_message
            if isinstance(request_logs, list):
                request_logs.append(row)
                _save("request_logs.json", request_logs)
        except Exception:
            return

    # Validate folder_id pattern
    if not isinstance(folder_id, str):
        _log(None, 400, "VALIDATION_ERROR", "folder_id must be a string")
        return _err("VALIDATION_ERROR", "folder_id must be a string")
    if not re.match(r"^hv_rfd_[0-9A-HJKMNP-TV-Z]{10,}$", folder_id):
        _log(None, 400, "VALIDATION_ERROR", "folder_id does not match required format")
        return _err("VALIDATION_ERROR", "folder_id does not match required format")

    # Ambient authentication
    authed = None
    for a in accounts if isinstance(accounts, list) else []:
        if a.get("status") == "active":
            authed = a
            break
    if not authed:
        _log(None, 401, "UNAUTHORIZED", "not authenticated")
        return _err("UNAUTHORIZED", "not authenticated")

    # Quota counter increment (reads allowed)
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    changed = _reset_daily_if_needed(authed, now_dt)
    authed["daily_request_count"] = int(authed.get("daily_request_count") or 0) + 1
    authed["updated_at"] = _now_iso()
    lim = int(authed.get("daily_request_limit") or 0)
    if lim > 0 and authed["daily_request_count"] > lim:
        authed["daily_request_count"] = lim
    if isinstance(accounts, list):
        for i, a in enumerate(accounts):
            if a.get("id") == authed.get("id"):
                accounts[i] = authed
                changed = True
                break
        if changed:
            _save("accounts.json", accounts)

    acct_id = authed.get("id")
    folder = None
    for f in routine_folders if isinstance(routine_folders, list) else []:
        if f.get("id") == folder_id and f.get("account_id") == acct_id:
            folder = f
            break

    if not folder:
        _log(acct_id, 404, "NOT_FOUND", "routine folder not found")
        return _err("NOT_FOUND", "routine folder not found")

    resp = {
        "data": {
            "id": folder.get("id"),
            "title": folder.get("title"),
            "index": folder.get("index"),
            "status": folder.get("status"),
            "hevy_folder_id": folder.get("hevy_folder_id"),
            "created_at": folder.get("created_at"),
            "updated_at": folder.get("updated_at"),
        }
    }
    _log(acct_id, 200)
    return resp

def create_routine_folder(title, **_extra):
    import json, os, datetime

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0160000" if __import__("os").path.isdir("./environment_mix/0160000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat()
        return _now().isoformat()

    def _parse_dt(v):
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str) or not v:
            return None
        s = v.strip()
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except ValueError:
            return None

    def _new_id(prefix, existing_rows):
        mx = 0
        for r in existing_rows:
            rid = r.get("id")
            if isinstance(rid, str) and rid.startswith(prefix):
                tail = rid[len(prefix) :]
                if tail.isdigit():
                    mx = max(mx, int(tail))
        return f"{prefix}{mx+1:06d}"

    # -------- request logging + quota ----------
    started = _now()
    reqlogs = _load("request_logs.json")
    if not isinstance(reqlogs, list):
        reqlogs = []

    def _log_and_return(payload, account_id=None, status="error", error_code=None):
        ended = _now()
        latency_ms = int((ended - started).total_seconds() * 1000)
        reqlogs.append(
            {
                "id": _new_id("req_", reqlogs),
                "endpoint": "create-routine-folder",
                "account_id": account_id,
                "status": status,
                "error_code": error_code,
                "latency_ms": latency_ms,
                "created_at": ended.isoformat(),
            }
        )
        _save("request_logs.json", reqlogs)
        return payload

    # -------- validation ----------
    if not isinstance(title, str):
        return _log_and_return(_err("VALIDATION_ERROR", "title must be a string"), status="error", error_code="VALIDATION_ERROR")
    if title.strip() == "":
        return _log_and_return(_err("VALIDATION_ERROR", "title must not be empty"), status="error", error_code="VALIDATION_ERROR")

    accounts = _load("accounts.json")
    if not isinstance(accounts, list):
        accounts = []

    # Ambient auth: pick an account that can serve the call (active preferred).
    acct = None
    for a in accounts:
        if isinstance(a, dict) and a.get("status") == "active":
            acct = a
            break
    if acct is None:
        for a in accounts:
            if isinstance(a, dict) and a.get("status") in ("active", "suspended", "revoked"):
                acct = a
                break
    if acct is None:
        return _log_and_return(_err("UNAUTHORIZED", "No authenticated account available"), status="error", error_code="UNAUTHORIZED")

    # enforce daily reset + increment consistently
    now = _now()
    reset_at = _parse_dt(acct.get("daily_count_reset_at"))
    if reset_at is None:
        reset_at = now
    if now >= reset_at:
        acct["daily_request_count"] = 0
        acct["daily_count_reset_at"] = (now + datetime.timedelta(days=1)).isoformat()

    # Quota enforcement for mutating tools
    limit = acct.get("daily_request_limit")
    try:
        limit = int(limit)
    except Exception:
        limit = 0
    try:
        count = int(acct.get("daily_request_count", 0))
    except Exception:
        count = 0

    if limit > 0 and count >= limit:
        # still count this request attempt
        acct["daily_request_count"] = count + 1
        acct["updated_at"] = now.isoformat()
        for i, a in enumerate(accounts):
            if a.get("id") == acct.get("id"):
                accounts[i] = acct
                break
        _save("accounts.json", accounts)
        return _log_and_return(
            _err("QUOTA_EXCEEDED", "Daily request limit exceeded", daily_request_limit=limit, daily_request_count=acct["daily_request_count"]),
            account_id=acct.get("id"),
            status="error",
            error_code="QUOTA_EXCEEDED",
        )

    # count this call
    acct["daily_request_count"] = count + 1
    acct["updated_at"] = now.isoformat()
    for i, a in enumerate(accounts):
        if a.get("id") == acct.get("id"):
            accounts[i] = acct
            break
    _save("accounts.json", accounts)

    folders = _load("routine_folders.json")
    if not isinstance(folders, list):
        folders = []

    # shift existing active folders down for this account (atomic within this function)
    for f in folders:
        if not isinstance(f, dict):
            continue
        if f.get("account_id") != acct.get("id"):
            continue
        if f.get("status") == "active":
            try:
                f["index"] = int(f.get("index", 0)) + 1
            except Exception:
                f["index"] = 1
            f["updated_at"] = now.isoformat()

    # ensure uniqueness of (account_id, hevy_folder_id) - generate a new upstream id if absent
    # since this is a local backend cache, we mint a stable synthetic upstream id.
    existing_upstream = set(
        f.get("hevy_folder_id")
        for f in folders
        if isinstance(f, dict) and f.get("account_id") == acct.get("id") and isinstance(f.get("hevy_folder_id"), str)
    )
    hevy_folder_id = _new_id("hfolder_", [{"id": x.replace("hfolder_", "")} for x in []])  # placeholder to keep format
    # better: mint by scanning existing_upstream numeric suffix if present
    mx = 0
    for v in existing_upstream:
        if isinstance(v, str) and v.startswith("hfolder_"):
            tail = v[len("hfolder_") :]
            if tail.isdigit():
                mx = max(mx, int(tail))
    hevy_folder_id = f"hfolder_{mx+1:06d}"

    folder_id = _new_id("rf_", folders)
    new_row = {
        "id": folder_id,
        "account_id": acct.get("id"),
        "hevy_folder_id": hevy_folder_id,
        "title": title,
        "index": 0,
        "status": "active",
        "created_at": now.isoformat(),
        "updated_at": now.isoformat(),
    }
    folders.append(new_row)
    _save("routine_folders.json", folders)

    return _log_and_return(
        {
            "routine_folder": new_row
        },
        account_id=acct.get("id"),
        status="ok",
    )

