    def _log_and_return(payload, account_id=None, status_str="error", error_code=None):
        ended = _now()
        latency_ms = int((ended - started).total_seconds() * 1000)
        reqlogs.append(
            {
                "id": _new_id("req_", reqlogs),
                "endpoint": "update-workout-status",
                "account_id": account_id,
                "status": status_str,
                "error_code": error_code,
                "latency_ms": latency_ms,
                "created_at": ended.isoformat(),
            }
        )
        _save("request_logs.json", reqlogs)
        return payload

    # -------- validation ----------
    if not isinstance(hevy_workout_id, str) or hevy_workout_id.strip() == "":
        return _log_and_return(_err("VALIDATION_ERROR", "hevy_workout_id must be a non-empty string"), status_str="error", error_code="VALIDATION_ERROR")
    if status != "deleted":
        return _log_and_return(_err("VALIDATION_ERROR", "Unsupported status", allowed=["deleted"]), status_str="error", error_code="VALIDATION_ERROR")

    accounts = _load("accounts.json")
    if not isinstance(accounts, list):
        accounts = []

    # Ambient auth: choose an account that has a matching workout (prerequisite), else any active.
    workouts = _load("workouts.json")
    if not isinstance(workouts, list):
        workouts = []

    candidate_accounts = []
    for a in accounts:
        if not isinstance(a, dict):
            continue
        if a.get("status") != "active":
            continue
        aid = a.get("id")
        if any(isinstance(w, dict) and w.get("account_id") == aid and w.get("hevy_workout_id") == hevy_workout_id for w in workouts):
            candidate_accounts.append(a)

    acct = candidate_accounts[0] if candidate_accounts else None
    if acct is None:
        for a in accounts:
            if isinstance(a, dict) and a.get("status") == "active":
                acct = a
                break
    if acct is None:
        for a in accounts:
            if isinstance(a, dict) and a.get("status") in ("active", "suspended", "revoked"):
                acct = a
                break
    if acct is None:
        return _log_and_return(_err("UNAUTHORIZED", "No authenticated account available"), status_str="error", error_code="UNAUTHORIZED")

    # daily reset + increment consistently
    now = _now()
    reset_at = _parse_dt(acct.get("daily_count_reset_at"))
    if reset_at is None:
        reset_at = now
    if now >= reset_at:
        acct["daily_request_count"] = 0
        acct["daily_count_reset_at"] = (now + datetime.timedelta(days=1)).isoformat()

    # quota for mutating tools
    try:
        limit = int(acct.get("daily_request_limit", 0))
    except Exception:
        limit = 0
    try:
        count = int(acct.get("daily_request_count", 0))
    except Exception:
        count = 0

    if limit > 0 and count >= limit:
        acct["daily_request_count"] = count + 1
        acct["updated_at"] = now.isoformat()
        for i, a in enumerate(accounts):
            if a.get("id") == acct.get("id"):
                accounts[i] = acct
                break
        _save("accounts.json", accounts)
        return _log_and_return(
            _err("QUOTA_EXCEEDED", "Daily request limit exceeded", daily_request_limit=limit, daily_request_count=acct["daily_request_count"]),
            account_id=acct.get("id"),
            status_str="error",
            error_code="QUOTA_EXCEEDED",
        )

    acct["daily_request_count"] = count + 1
    acct["updated_at"] = now.isoformat()
    for i, a in enumerate(accounts):
        if a.get("id") == acct.get("id"):
            accounts[i] = acct
            break
    _save("accounts.json", accounts)

    # locate workout by (account_id, hevy_workout_id)
    w_idx = None
    workout = None
    for i, w in enumerate(workouts):
        if not isinstance(w, dict):
            continue
        if w.get("account_id") == acct.get("id") and w.get("hevy_workout_id") == hevy_workout_id:
            w_idx = i
            workout = w
            break

    if workout is None:
        return _log_and_return(_err("NOT_FOUND", "Workout not found", hevy_workout_id=hevy_workout_id), account_id=acct.get("id"), status_str="error", error_code="NOT_FOUND")

    # lifecycle transition enforcement: active -> deleted only
    current = workout.get("status")
    if current == "deleted":
        # idempotent: already deleted; ensure a corresponding event exists at/after this update? Real APIs vary.
        # We won't append duplicate deleted event; return current workout.
        return _log_and_return({"workout": workout}, account_id=acct.get("id"), status_str="ok")

    if current != "active":
        return _log_and_return(
            _err("INVALID_TRANSITION", "Illegal status transition", from_status=current, to_status="deleted"),
            account_id=acct.get("id"),
            status_str="error",
            error_code="INVALID_TRANSITION",
        )

    # apply soft delete
    workout["status"] = "deleted"
    workout["updated_at"] = now.isoformat()
    # business rule: if deleted, exercises may be empty but preserve title/started_at/ended_at; we keep as-is.
    workouts[w_idx] = workout
    _save("workouts.json", workouts)

    # append workout_events row (event_type='deleted', effective_at=now())
    events = _load("workout_events.json")
    if not isinstance(events, list):
        events = []

    ev = {
        "id": _new_id("we_", events),
        "account_id": acct.get("id"),
        "workout_id": workout.get("id"),
        "hevy_workout_id": hevy_workout_id,
        "event_type": "deleted",
        "effective_at": now.isoformat(),
        "payload_snapshot": None,
        "created_at": now.isoformat(),
        "updated_at": now.isoformat(),
    }
    # Foreign key integrity: workout_id must belong to same account (it does, by lookup)
    events.append(ev)
    _save("workout_events.json", events)

    return _log_and_return(
        {"workout": workout, "workout_event": ev},
        account_id=acct.get("id"),
        status_str="ok",
    )

def update_routine_status(routine_id, status, **_extra):
    import json, os, datetime, time

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0160000" if __import__("os").path.isdir("./environment_mix/0160000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if not isinstance(dt, datetime.datetime):
            dt = _now_utc()
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _ensure_request_log_file():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            try:
                with open(path, "w", encoding="utf-8") as f:
                    json.dump([], f)
            except Exception:
                return False
        return True

    def _log(account_id, endpoint, status_text, error_code=None):
        if not _ensure_request_log_file():
            return
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": "hv_req_" + str(int(time.time() * 1000)),
                "account_id": account_id,
                "endpoint": endpoint,
                "status": status_text,
                "error_code": error_code,
                "latency_ms": int((time.time() - _t0) * 1000),
                "timestamp": _iso(_now_utc()),
            }
        )
        _save("request_logs.json", logs)

    def _select_account():
        accounts = _load("accounts.json")
        if isinstance(accounts, dict) and "rows" in accounts:
            accounts = accounts.get("rows", [])
        if not isinstance(accounts, list):
            return None
        for a in accounts:
            if isinstance(a, dict) and a.get("status") == "active":
                return a
        for a in accounts:
            if isinstance(a, dict):
                return a
        return None

    if not isinstance(routine_id, str) or not routine_id.strip():
        acct = _select_account()
        _log(acct["id"] if acct else None, "update-routine-status", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "routine_id must be a string", field="routine_id")
    if status not in ("active", "archived", "deleted"):
        acct = _select_account()
        _log(acct["id"] if acct else None, "update-routine-status", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be one of: active, archived, deleted", field="status")

    acct = _select_account()
    if not acct:
        _log(None, "update-routine-status", "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authenticated account context available")

    now = _now_utc()
    accounts = _load("accounts.json")
    if isinstance(accounts, dict) and "rows" in accounts:
        acc_rows = accounts.get("rows", [])
        wrapper = True
    else:
        acc_rows = accounts if isinstance(accounts, list) else []
        wrapper = False
    acct_row = None
    for a in acc_rows:
        if isinstance(a, dict) and a.get("id") == acct.get("id"):
            acct_row = a
            break
    if acct_row is None:
        _log(acct.get("id"), "update-routine-status", "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Account context not found")

    # quota enforcement for mutation
    limit = int(acct_row.get("daily_request_limit") or 0)
    count = int(acct_row.get("daily_request_count") or 0)
    if limit > 0 and count >= limit:
        _log(acct_row.get("id"), "update-routine-status", "error", "QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Daily request limit exceeded")

    routines = _load("routines.json")
    if isinstance(routines, dict) and "rows" in routines:
        routine_rows = routines.get("rows", [])
        routines_wrapper = True
    else:
        routine_rows = routines if isinstance(routines, list) else []
        routines_wrapper = False

    target = None
    for r in routine_rows:
        if not isinstance(r, dict):
            continue
        if r.get("account_id") != acct_row.get("id"):
            continue
        if r.get("id") == routine_id:
            target = r
            break

    if target is None:
        # tolerate caller passing account id: choose newest routine for account
        if routine_id == acct_row.get("id"):
            candidates = [r for r in routine_rows if isinstance(r, dict) and r.get("account_id") == acct_row.get("id")]
            if candidates:
                candidates.sort(key=lambda x: x.get("created_at") or "", reverse=True)
                target = candidates[0]

    if target is None:
        _log(acct_row.get("id"), "update-routine-status", "error", "NOT_FOUND")
        return _err("NOT_FOUND", "Routine not found for this account")

    current = target.get("status")
    transitions = {"active": ["archived", "deleted"], "archived": ["active", "deleted"], "deleted": []}
    if current not in transitions:
        _log(acct_row.get("id"), "update-routine-status", "error", "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", f"Routine has invalid current status '{current}'")
    if status == current:
        # idempotent OK, but still counts
        acct_row["daily_request_count"] = count + 1
        acct_row["updated_at"] = _iso(now)
        if wrapper:
            accounts["rows"] = acc_rows
            _save("accounts.json", accounts)
        else:
            _save("accounts.json", acc_rows)
        _log(acct_row.get("id"), "update-routine-status", "ok", None)
        return {"routine": target}
    if status not in transitions[current]:
        _log(acct_row.get("id"), "update-routine-status", "error", "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", f"Cannot transition routine from '{current}' to '{status}'")

    target["status"] = status
    target["updated_at"] = _iso(now)

    if routines_wrapper:
        routines["rows"] = routine_rows
        _save("routines.json", routines)
    else:
        _save("routines.json", routine_rows)

    acct_row["daily_request_count"] = count + 1
    acct_row["updated_at"] = _iso(now)
    if wrapper:
        accounts["rows"] = acc_rows
        _save("accounts.json", accounts)
    else:
        _save("accounts.json", acc_rows)

    _log(acct_row.get("id"), "update-routine-status", "ok", None)
    return {"routine": target}

def update_routine_folder_status(folder_id, status, **_extra):
    import json, os, datetime, time, random

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0160000" if __import__("os").path.isdir("./environment_mix/0160000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if not isinstance(dt, datetime.datetime):
            dt = _now_utc()
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s):
        if not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    def _base32_ulid_like(n=26):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return "".join(random.choice(alphabet) for _ in range(n))

    def _new_req_id():
        return "hv_req_" + _base32_ulid_like(26)

    def _ensure_request_log_file():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            try:
                with open(path, "w", encoding="utf-8") as f:
                    json.dump([], f)
            except Exception:
                return False
        return True

    def _log(account_id, endpoint, status_text, error_code=None):
        if not _ensure_request_log_file():
            return
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_req_id(),
            "account_id": account_id,
            "endpoint": endpoint,
            "status": status_text,
            "error_code": error_code,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _iso(_now_utc())
        })
        _save("request_logs.json", logs)

    def _pick_account():
        accounts = _load("accounts.json")
        if not isinstance(accounts, list):
            accounts = []
        for a in accounts:
            if isinstance(a, dict) and a.get("status") == "active" and isinstance(a.get("id"), str):
                return a, accounts
        return None, accounts

    def _reset_and_check_quota(acct):
        now_dt = _now_utc()
        reset_at = _parse_rfc3339(acct.get("daily_count_reset_at")) if isinstance(acct.get("daily_count_reset_at"), str) else None
        if reset_at is None:
            reset_at = now_dt
        if now_dt >= reset_at:
            acct["daily_request_count"] = 0
            next_midnight = (now_dt.astimezone(datetime.timezone.utc).replace(hour=0, minute=0, second=0, microsecond=0) +
                             datetime.timedelta(days=1))
            acct["daily_count_reset_at"] = _iso(next_midnight)
        limit = acct.get("daily_request_limit", 0)
        cnt = acct.get("daily_request_count", 0)
        if not isinstance(limit, int) or limit < 0:
            return _err("CONFLICT", "Account daily_request_limit is invalid.")
        if not isinstance(cnt, int) or cnt < 0:
            return _err("CONFLICT", "Account daily_request_count is invalid.")
        if limit > 0 and cnt >= limit:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.")
        acct["daily_request_count"] = cnt + 1
        acct["updated_at"] = _iso(now_dt)
        return None

    # NOTE: tool schema claims hv_rtf_ but actual datastore uses hv_rfd_. Accept both.
    if not isinstance(folder_id, str) or not folder_id.strip():
        acct, _ = _pick_account()
        _log(acct.get("id") if acct else None, "update-routine-folder-status", "VALIDATION_ERROR", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "folder_id must be a non-empty string", field="folder_id")
    if not isinstance(status, str) or status != "deleted":
        acct, _ = _pick_account()
        _log(acct.get("id") if acct else None, "update-routine-folder-status", "VALIDATION_ERROR", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be 'deleted'", field="status")

    acct, accounts_all = _pick_account()
    if not acct:
        _log(None, "update-routine-folder-status", "UNAUTHORIZED", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active account available.")
    account_id = acct.get("id")

    qerr = _reset_and_check_quota(acct)
    if qerr:
        _log(account_id, "update-routine-folder-status", qerr["error"]["code"], qerr["error"]["code"])
        return qerr

    folders = _load("routine_folders.json")
    if not isinstance(folders, list):
        folders = []

    idx = None
    row = None
    for i, f in enumerate(folders):
        if isinstance(f, dict) and f.get("account_id") == account_id and f.get("id") == folder_id:
            idx = i
            row = f
            break

    if row is None:
        for i, a in enumerate(accounts_all):
            if isinstance(a, dict) and a.get("id") == account_id:
                accounts_all[i] = acct
                _save("accounts.json", accounts_all)
                break
        _log(account_id, "update-routine-folder-status", "NOT_FOUND", "NOT_FOUND")
        return _err("NOT_FOUND", "Routine folder not found for this account.")

    current = row.get("status")
    transitions = {"active": ["deleted"], "deleted": []}
    if current not in transitions:
        _log(account_id, "update-routine-folder-status", "CONFLICT", "CONFLICT")
        return _err("CONFLICT", "Routine folder has invalid current status.")
    if status == current:
        for i, a in enumerate(accounts_all):
            if isinstance(a, dict) and a.get("id") == account_id:
                accounts_all[i] = acct
                _save("accounts.json", accounts_all)
                break
        _log(account_id, "update-routine-folder-status", "OK", None)
        return {"routine_folder": row}
    if status not in transitions[current]:
        _log(account_id, "update-routine-folder-status", "INVALID_TRANSITION", "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", f"Cannot transition routine folder from {current} to {status}.")

    row["status"] = "deleted"
    row["updated_at"] = _iso(_now_utc())
    folders[idx] = row
    _save("routine_folders.json", folders)

    for i, a in enumerate(accounts_all):
        if isinstance(a, dict) and a.get("id") == account_id:
            accounts_all[i] = acct
            _save("accounts.json", accounts_all)
            break

    _log(account_id, "update-routine-folder-status", "OK", None)
    return {"routine_folder": row}

def update_exercise_template_status(exercise_template_id, status, **_extra):
    import json, os, datetime, time, re

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0160000" if __import__("os").path.isdir("./environment_mix/0160000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if not isinstance(dt, datetime.datetime):
            dt = _now_utc()
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _ensure_request_log_file():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            with open(path, "w", encoding="utf-8") as f:
                json.dump([], f)
        return True

    def _unwrap_rows(x):
        if isinstance(x, dict) and "rows" in x and isinstance(x["rows"], list):
            return x["rows"]
        if isinstance(x, list):
            return x
        return []

    def _log(account_id, endpoint, status_text, error_code=None):
        _ensure_request_log_file()
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": "hv_req_" + str(int(time.time() * 1000)),
                "account_id": account_id,
                "endpoint": endpoint,
                "status": status_text,
                "error_code": error_code,
                "latency_ms": int((time.time() - _t0) * 1000),
                "timestamp": _iso(_now_utc()),
            }
        )
        _save("request_logs.json", logs)

    def _parse_dt(s):
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _reset_and_increment_daily(accounts, account_row):
        now = _now_utc()
        reset_at = _parse_dt(account_row.get("daily_count_reset_at"))
        if reset_at is None:
            reset_at = now
        if now >= reset_at:
            account_row["daily_request_count"] = 0
            account_row["daily_count_reset_at"] = _iso(now + datetime.timedelta(days=1))
        cnt = account_row.get("daily_request_count")
        if not isinstance(cnt, int) or cnt < 0:
            cnt = 0
        account_row["daily_request_count"] = cnt + 1
        account_row["updated_at"] = _iso(now)
        return accounts

    endpoint = "update-exercise-template-status"

    # Validate inputs. Accept legacy ext_* ids as well to match real-world/data usage.
    if not isinstance(exercise_template_id, str) or not exercise_template_id.strip():
        err = _err("VALIDATION_ERROR", "exercise_template_id is required", field="exercise_template_id")
        _log(None, endpoint, "error", err["error"]["code"])
        return err
    exercise_template_id = exercise_template_id.strip()
    if not (re.match(r"^hv_ext_[0-9A-HJKMNP-TV-Z]{10,}$", exercise_template_id) or re.match(r"^ext_[A-Za-z0-9_\-]{2,}$", exercise_template_id)):
        err = _err(
            "VALIDATION_ERROR",
            "exercise_template_id must match '^hv_ext_[0-9A-HJKMNP-TV-Z]{10,}$' (or legacy 'ext_*' id)",
            field="exercise_template_id",
        )
        _log(None, endpoint, "error", err["error"]["code"])
        return err

    if not isinstance(status, str) or status not in ("deleted",):
        err = _err("VALIDATION_ERROR", "status must be 'deleted'", field="status")
        _log(None, endpoint, "error", err["error"]["code"])
        return err

    accounts = _unwrap_rows(_load("accounts.json"))
    templates = _unwrap_rows(_load("exercise_templates.json"))

    # Resolve template and owning active account (ambient auth).
    template_idx = None
    template_row = None
    for i, t in enumerate(templates):
        if isinstance(t, dict) and t.get("id") == exercise_template_id:
            template_idx = i
            template_row = t
            break

    if template_row is None:
        _log(None, endpoint, "error", "NOT_FOUND")
        return _err("NOT_FOUND", "Exercise template not found", field="exercise_template_id")

    acct_id = template_row.get("account_id")
    account_row = None
    for a in accounts:
        if isinstance(a, dict) and a.get("id") == acct_id:
            account_row = a
            break

    if account_row is None or account_row.get("status") != "active":
        err = _err("UNAUTHORIZED", "No authenticated active account can perform this operation")
        _log(acct_id if isinstance(acct_id, str) else None, endpoint, "error", err["error"]["code"])
        return err

    # Increment usage first (every call). Then enforce quota for mutation.
    try:
        accounts = _reset_and_increment_daily(accounts, account_row)
        _save("accounts.json", accounts)
    except Exception:
        err = _err("CONFLICT", "Failed to persist account usage counters")
        _log(account_row.get("id"), endpoint, "error", err["error"]["code"])
        return err

    limit = account_row.get("daily_request_limit")
    cnt = account_row.get("daily_request_count")
    if isinstance(limit, int) and limit > 0 and isinstance(cnt, int) and cnt > limit:
        # If increment pushed us over, refuse mutation (consistent with "at least increment daily_request_count").
        err = _err("QUOTA_EXCEEDED", "Daily request limit exceeded for this account")
        _log(account_row.get("id"), endpoint, "error", err["error"]["code"])
        return err

    # Lifecycle transition: active -> deleted only; deleted is terminal.
    cur = template_row.get("status")
    if cur not in ("active", "deleted"):
        err = _err("VALIDATION_ERROR", "Template has invalid current status", field="status")
        _log(account_row.get("id"), endpoint, "error", err["error"]["code"])
        return err

    if cur == "deleted":
        # Idempotent: already deleted; no further mutation required, but must not claim success without effect.
        # Since idempotent delete is a real behavior, returning the existing row is acceptable.
        _log(account_row.get("id"), endpoint, "ok", None)
        return {"data": template_row}

    # Perform transition
    now = _now_utc()
    templates[template_idx]["status"] = "deleted"
    templates[template_idx]["updated_at"] = _iso(now)

    try:
        _save("exercise_templates.json", templates)
    except Exception:
        err = _err("CONFLICT", "Failed to persist exercise template status update")
        _log(account_row.get("id"), endpoint, "error", err["error"]["code"])
        return err

    _log(account_row.get("id"), endpoint, "ok", None)
    return {"data": templates[template_idx]}

def update_account_status(status, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0160000" if __import__("os").path.isdir("./environment_mix/0160000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    def _parse_dt(v):
        if isinstance(v, datetime.datetime):
            return v
        if not isinstance(v, str) or not v:
            return None
        s = v.strip()
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _ensure_request_log():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            try:
                with open(path, "w", encoding="utf-8") as f:
                    json.dump([], f)
            except Exception:
                return False
        return True

    def _log_call(account_id, used_credential, endpoint, status_code, error_code=None):
        if not _ensure_request_log():
            return
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
            "account_id": account_id,
            "credential": used_credential,
            "endpoint": endpoint,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now_iso
        })
        _save("request_logs.json", logs)

    def _select_account_for_call(allow_revoked=False):
        accounts = _load("accounts.json")
        if not isinstance(accounts, list) or not accounts:
            return None
        for a in accounts:
            if not isinstance(a, dict) or not a.get("id"):
                continue
            st = a.get("status")
            if allow_revoked:
                if st in ("active", "suspended", "revoked"):
                    return a
            else:
                if st in ("active", "suspended"):
                    return a
        return None

    def _maybe_reset_daily_counter(acct):
        reset_at = _parse_dt(acct.get("daily_count_reset_at"))
        if reset_at is None:
            tomorrow = (now + datetime.timedelta(days=1)).date()
            next_midnight = datetime.datetime.combine(tomorrow, datetime.time(0, 0, 0))
            acct["daily_request_count"] = int(acct.get("daily_request_count") or 0)
            acct["daily_count_reset_at"] = next_midnight.isoformat() + "Z"
            return True
        if now >= reset_at:
            tomorrow = (now + datetime.timedelta(days=1)).date()
            next_midnight = datetime.datetime.combine(tomorrow, datetime.time(0, 0, 0))
            acct["daily_request_count"] = 0
            acct["daily_count_reset_at"] = next_midnight.isoformat() + "Z"
            return True
        return False

    def _increment_usage_and_enforce_mutation_quota(acct, accounts_rows):
        _maybe_reset_daily_counter(acct)
        limit = acct.get("daily_request_limit")
        try:
            limit = int(limit)
        except Exception:
            return (False, _err("VALIDATION_ERROR", "Account daily_request_limit is invalid."))
        if limit < 0:
            return (False, _err("VALIDATION_ERROR", "Account daily_request_limit must be >= 0."))
        cnt = acct.get("daily_request_count")
        try:
            cnt = int(cnt)
        except Exception:
            cnt = 0
        if limit > 0 and cnt >= limit:
            return (False, _err("RATE_LIMIT", "Daily request quota exceeded.", daily_request_limit=limit, daily_request_count=cnt))
        acct["daily_request_count"] = cnt + 1
        acct["updated_at"] = now_iso
        for i, a in enumerate(accounts_rows):
            if isinstance(a, dict) and a.get("id") == acct.get("id"):
                accounts_rows[i] = acct
                break
        _save("accounts.json", accounts_rows)
        return (True, None)

    endpoint = "update-account-status"

    if status not in ("active", "revoked", "suspended"):
        acct = _select_account_for_call(allow_revoked=True)
        _log_call(acct["id"] if acct else None, None, endpoint, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid status.", field="status")

    accounts = _load("accounts.json")
    if not isinstance(accounts, list) or not accounts:
        _log_call(None, None, endpoint, 401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authenticated account available.")

    # For changing account status, allow selecting even revoked account (so it can stay revoked/idempotent),
    # but transitions out of revoked are forbidden by lifecycle rules.
    acct = _select_account_for_call(allow_revoked=True)
    if not acct:
        _log_call(None, None, endpoint, 401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authenticated account available.")

    ok, e = _increment_usage_and_enforce_mutation_quota(acct, accounts)
    if not ok:
        _log_call(acct.get("id"), None, endpoint, 429, e["error"]["code"])
        return e

    current = acct.get("status")
    transitions = {
        "active": {"revoked", "suspended"},
        "suspended": {"active", "revoked"},
        "revoked": set()
    }
    if current not in transitions:
        _log_call(acct.get("id"), None, endpoint, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Account has invalid current status.", current_status=current)

    if status == current:
        _log_call(acct.get("id"), None, endpoint, 200, None)
        return {"account": acct}

    if status not in transitions[current]:
        # Tool description says FORBIDDEN, but allowed error codes list doesn't include it; use INVALID_TRANSITION.
        _log_call(acct.get("id"), None, endpoint, 409, "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Unsupported account status transition.", from_status=current, to_status=status)

    acct["status"] = status
    acct["updated_at"] = now_iso
    for i, a in enumerate(accounts):
        if isinstance(a, dict) and a.get("id") == acct.get("id"):
            accounts[i] = acct
            break
    _save("accounts.json", accounts)

    _log_call(acct.get("id"), None, endpoint, 200, None)
    return {"account": acct}
